        /// <summary>
        /// Creates the outer array for a jagged shape whose scalar leaf type is T.<br/>
        /// Only the outer array is allocated; child-array slots remain null until filled.<br/>
        /// Returns a non-null array, including for zero outer count, or propagates the factory exception.<br/>
        /// </summary>
        /// <typeparam name="T">The leaf type to wrap in the requested number of array levels.<br/></typeparam>
        /// <param name="depth">The positive number of array levels, with one denoting T[].<br/></param>
        /// <param name="outerCount">The nonnegative number of slots in the outer array.<br/></param>
        /// <returns>The newly allocated outer array with its exact jagged CLR type.<br/></returns>
        /// <exception cref="ArgumentOutOfRangeException">Depth is less than one or outerCount is negative.<br/></exception>
        public static Array CreateJaggedArray<T>(int depth, int outerCount)
        {
            return CreateJaggedArray(typeof(T), depth, outerCount);
        }
        /// <summary>
        /// Allocates only the outer array of the requested jagged CLR shape. Depth one means a leaf-type array; inner array slots remain null until filled.<br/>
        /// </summary>
        /// <param name="elementType">CLR leaf element type before wrapping it in the requested array levels.<br/></param>
        /// <param name="depth">Positive number of jagged array levels, with one denoting a leaf-type array.<br/></param>
        /// <param name="outerCount">Nonnegative length of the newly allocated outer array.<br/></param>
        /// <returns>New outer array with the requested jagged CLR type and uninitialized inner-array slots.<br/></returns>
        /// <exception cref="ArgumentOutOfRangeException">Depth is less than one or outerCount is negative.<br/></exception>
        public static Array CreateJaggedArray(Type elementType, int depth, int outerCount)
        {
            if (elementType == null) throw new ArgumentNullException(nameof(elementType));
            if (depth < 1) throw new ArgumentOutOfRangeException(nameof(depth));
            if (outerCount < 0) throw new ArgumentOutOfRangeException(nameof(outerCount));

            // Get or build jagged array type
            var jaggedType = _jaggedTypeCache.GetOrAdd((elementType, depth), key =>
            {
                var (etype, d) = key;
                var t = etype;
                for (int i = 0; i < d; i++)
                    t = t.MakeArrayType();   // wrap with [] depth times
                return t;
            });

            // Allocate the outermost array
            return Array.CreateInstance(jaggedType.GetElementType()!, outerCount);
        }
        /// <summary>
        /// Creates or resolves a zero-input/singleton shape classified for the special StaticClass representation; it can still have readonly scalar members.<br/>
        /// These are typically utility or singleton-like types such as <see cref="System.StringComparer.OrdinalIgnoreCase"/>, 
        /// <see cref="System.Text.Encoding.UTF8"/>, <see cref="System.DBNull.Value"/>, and similar.<br/>
        /// Resolution follows a waterfall strategy:
        /// <list type="number">
        /// <item><description>Custom activators provided by the caller.</description></item>
        /// <item><description>Public parameterless constructor, if available.</description></item>
        /// <item><description>Public static properties of the type.</description></item>
        /// <item><description>Public static fields of the type.</description></item>
        /// <item><description>Public and non-public static parameterless methods returning the type.</description></item>
        /// <item><description>If none match, returns <c>null</c>.</description></item>
        /// </list>
        /// Developer activators are resolved from the current options on every call, including intentional null results.<br/>
        /// Only intrinsic type-construction delegates are cached; option instances and their callbacks are never retained in that cache.<br/>
        /// The caller supplies the already-selected Type; this helper does not resolve or approve a stored type-name string itself.<br/>
        /// </summary>
        /// <param name="binary">The inheto binary providing context for the activation.</param>
        /// <param name="propPath">The current property path being materialized.</param>
        /// <param name="staticType">The type to attempt rehydration for.</param>
        /// <param name="dzOptions">Optional deserialization options used to resolve custom activators.</param>
        /// <returns>An instance of the requested type, or <c>null</c> if no activation path is available.</returns>
        public static object? CreateZeroZeroType(InhetoBinary binary, string propPath, Type staticType, DeserializationOptions? dzOptions)
        {
            var context = new DeserializationOptions.ActivatorContext(binary, propPath, staticType);
            if (dzOptions != null && dzOptions.TryGetActivator(staticType, out var customActivator))
                return customActivator(context);

            // Cache only intrinsic construction; developer authority is current-call state.
            var activator = _activatorCache.GetOrAdd(staticType, BuildZeroInputActivator);
            return activator(context);
        }
        /// <summary>
        /// Serializes a non-null object graph and creates an addressable reader over the resulting plain Inheto binary payload.<br/>
        /// </summary>
        /// <param name="source">Non-null source object graph to serialize; developer getters, enumerators and custom serializers may execute.<br/></param>
        /// <param name="szOptions">Optional serialization registrations and member policy, forwarded unchanged to the writer.<br/></param>
        /// <param name="dzOptions">Optional deserialization policy retained by the resulting reader.<br/></param>
        /// <returns>Reader over the serialized payload; borrowed views depend on that payload remaining valid.<br/></returns>
        /// <remarks>
        /// Inheto does not compress or encrypt its payload. Callers may transform <see cref="RawSpan"/>, <see cref="RawMemory"/> or <see cref="RawBytes"/> for storage or transport.<br/>
        /// Decrypt and decompress transformed payloads before passing their plain Inheto bytes to <see cref="FromStream"/>.<br/>
        /// This convenience factory creates a writer for this graph; reuse <see cref="InhetoSerializer"/> explicitly when processing many graphs.<br/>
        /// </remarks>
        /// <exception cref="ArgumentNullException"><paramref name="source"/> is null.<br/></exception>
        public static InhetoBinary FromObject(object? source, SerializationOptions? szOptions = null, DeserializationOptions? dzOptions = null)
        {
            ArgumentNullException.ThrowIfNull(source);
            szOptions = szOptions ?? new SerializationOptions();
            dzOptions = dzOptions ?? new DeserializationOptions();
            var szr = new InhetoSerializer(szOptions);

            var stream = szr.Serialize(source);
            return new InhetoBinary(stream, szOptions, dzOptions);
        }


        /// <summary>
        /// Creates a reader over the supplied BufferStream without copying its plain Inheto payload and resets its cursor to zero. Keep that stream alive and unchanged for all borrowed navigation views.<br/>
        /// Caller-owned storage or transport compression/encryption must be reversed before this method is called; it does not detect or decode transformed envelopes.<br/>
        /// </summary>
        /// <param name="objectStream">Existing BufferStream containing a complete untransformed Inheto payload; borrowed without copying.<br/></param>
        /// <param name="dzOpts">Optional deserialization policy retained by the new reader.<br/></param>
        /// <returns>Reader over the serialized payload; borrowed views depend on that payload remaining valid.<br/></returns>
        public static InhetoBinary FromStream(BufferStream objectStream, DeserializationOptions? dzOpts = null) => new InhetoBinary(objectStream, null, dzOpts);

        /// <summary>
        /// Rebinds this binary reader to a new borrowed payload for allocation-sensitive sequential scans.<br/>
        /// Every payload-local name resolution, reference materialization, complete-name map, and owner context is cleared before the new bytes become observable.<br/>
        /// Static prepared-path/type caches and instance projection delegates remain reusable because they describe code or path shape rather than values from the prior payload.<br/>
        /// Callers must not retain borrowed name entries, raw-byte segments, or other views from the prior payload across this operation; detached values already returned to the caller remain valid.<br/>
        /// </summary>
        /// <param name="payload">New borrowed serialized Inheto payload.<br/></param>
        /// <param name="dzOpts">Optional deserialization policy for the new payload; omission creates the ordinary default policy.<br/></param>
        public void RebindBorrowedPayload(ReadOnlyMemory<byte> payload, DeserializationOptions? dzOpts = null)
        {
            stream.RebindReadOnlyMemory(payload);
            deserializationOptions = dzOpts ?? new DeserializationOptions();
            serializationOptions = null;
            _resolvedNameEntry = 0;
            _resolvedNameEntries?.Clear();
            _nameEntryCacheSuppressionDepth = 0;
            refCache?.Clear();
            materializationContext = null;
            allNames = null;
        }
        private static IAccessors? GetAccessors(Type tType, PropField prop)
        {
            IAccessors? acc = null;
            if (!TypeAccessors.TryGetValue(tType, out var accs))
            {
                TypeAccessors[tType] = new ConcurrentDictionary<MemberInfo, IAccessors>();
                accs = TypeAccessors[tType];
            }
            if (prop.Prop != null)
            {
                if (!accs.TryGetValue(prop.Prop, out acc))
                {
                    var factory = typeof(AccessorUtils).GetMethod("CreateAccessors", BindingFlags.Static | BindingFlags.NonPublic)
                        ?? throw new MissingMethodException(typeof(AccessorUtils).FullName, "CreateAccessors");
                    var method = factory.MakeGenericMethod(tType, prop.Type);
                    acc = method.Invoke(null, new object[] { prop.Prop }) as IAccessors
                        ?? throw new InvalidOperationException("The property accessor factory returned no compatible accessor.");
                    TypeAccessors[tType][prop.Prop] = acc;
                }
            }
            else if (prop.Field != null)
            {
                if (!accs.TryGetValue(prop.Field, out acc))
                {
                    var factory = typeof(AccessorUtils).GetMethod("CreateAccessors", BindingFlags.Static | BindingFlags.NonPublic)
                        ?? throw new MissingMethodException(typeof(AccessorUtils).FullName, "CreateAccessors");
                    var method = factory.MakeGenericMethod(tType, prop.Type);
                    acc = method.Invoke(null, new object[] { prop.Field }) as IAccessors
                        ?? throw new InvalidOperationException("The field accessor factory returned no compatible accessor.");
                    TypeAccessors[tType][prop.Field] = acc;
                }

            }

            return acc;
        }
        private static IAccessors? GetAccessors(Type tType, FieldInfo field)
        {
            if (!TypeAccessors.TryGetValue(tType, out var accs))
            {
                TypeAccessors[tType] = new ConcurrentDictionary<MemberInfo, IAccessors>();
                accs = TypeAccessors[tType];
            }
            if (!accs.TryGetValue(field, out var acc))
            {
                var factory = typeof(AccessorUtils).GetMethod("CreateAccessors", BindingFlags.Static | BindingFlags.NonPublic)
                    ?? throw new MissingMethodException(typeof(AccessorUtils).FullName, "CreateAccessors");
                var method = factory.MakeGenericMethod(tType, field.FieldType);
                acc = method.Invoke(null, new object[] { field }) as IAccessors
                    ?? throw new InvalidOperationException("The field accessor factory returned no compatible accessor.");
                TypeAccessors[tType][field] = acc;
            }

            return acc;
        }
        private static object? GetComparerIfAny(string propPath, DeserializationOptions dzOptions, Type tType, NameHeaderEntry nvn)
        {
            object? comparer = null;
            if (nvn.Kind == InhetoKindMasks.InhetoCollectionType && nvn.Type.CollectionInfo.Comparer != InhetoComparerTypes.None)
            {
                if (dzOptions.MemberComparers.TryGetValue(propPath, out var memberCmp))
                    comparer = memberCmp;
                else if (dzOptions.TypeComparers.TryGetValue(tType, out var typeCmp))
                    comparer = typeCmp;
                else
                    comparer = nvn.Type.CollectionInfo.Comparer switch
                    {
                        InhetoComparerTypes.Ordinal => StringComparer.Ordinal,
                        InhetoComparerTypes.OrdinalIgnoreCase => StringComparer.OrdinalIgnoreCase,
                        InhetoComparerTypes.CurrentCulture => StringComparer.CurrentCulture,
                        InhetoComparerTypes.CurrentCultureIgnoreCase => StringComparer.CurrentCultureIgnoreCase,
                        InhetoComparerTypes.InvariantCulture => StringComparer.InvariantCulture,
                        InhetoComparerTypes.InvariantCultureIgnoreCase => StringComparer.InvariantCultureIgnoreCase,
                        _ => null
                    };
            }
            else
            {
                if (dzOptions.MemberComparers.TryGetValue(propPath, out var memberCmp))
                    comparer = memberCmp;
                else if (dzOptions.TypeComparers.TryGetValue(tType, out var typeCmp))
                    comparer = typeCmp;
            }

            return comparer;
        }

