        //======  CONSTRUCTORS  ======
        /// <summary>
        /// Binds a reader directly to a plain Inheto stream and initializes its serialization/materialization policy references.<br/>
        /// Resets the supplied stream cursor without copying bytes or applying storage/transport transformations.<br/>
        /// </summary>
        /// <param name="objectStream">Plain indexed Inheto payload whose lifetime is supplied by the owner.<br/></param>
        /// <param name="szOpts">Optional serialization policy retained for related reader operations.<br/></param>
        /// <param name="dzOpts">Materialization policy to retain, or null to create the ordinary default.<br/></param>
        private InhetoBinary(BufferStream objectStream, SerializationOptions? szOpts, DeserializationOptions? dzOpts)
        {
            stream = objectStream;
            stream.Position = 0;
            serializationOptions = szOpts;
            deserializationOptions = dzOpts ?? new DeserializationOptions();
        }

        /// <summary>
        /// Gets the materialized-reference cache, creating it only for value shapes that use duplicate or mutable reference semantics.<br/>
        /// </summary>
        private Dictionary<uint, object> RefCache => refCache ??= new Dictionary<uint, object>();

        /// <summary>
        /// Gets lazily initialized, weakly keyed type-only fill dispatch shared across independent readers.<br/>
        /// Entries contain no reader, destination, payload, path or options; all operation state is passed to the delegate.<br/>
        /// </summary>
        private static ConditionalWeakTable<Type, Action<InhetoBinary, object, string, DeserializationOptions>> CacheReadPropOnto
            => FillDispatch.Cache;

        /// <summary>
        /// Associates owner-specific context with this payload for later root-object materialization.<br/>
        /// The context is not serialized and is preserved by shallow clones.<br/>
        /// </summary>
        /// <param name="context">Owner-defined context, such as a stable record identity.<br/></param>
        internal void SetMaterializationContext(object? context) => materializationContext = context;

        /// <summary>
        /// Tries to read the owner-specific context associated with this payload.<br/>
        /// The context remains process-local and is never read from or written to the serialized representation.<br/>
        /// </summary>
        /// <typeparam name="TContext">Expected owner-defined context type.<br/></typeparam>
        /// <param name="context">Typed context when the current association has the requested shape; otherwise its default value.<br/></param>
        /// <returns><see langword="true"/> when the payload carries a context of type <typeparamref name="TContext"/>; otherwise <see langword="false"/>.<br/></returns>
        internal bool TryGetMaterializationContext<TContext>(out TContext context)
        {
            if (materializationContext is TContext typed)
            {
                context = typed;
                return true;
            }

            context = default!;
            return false;
        }








        //======  PROPERTIES  ======
        /// <summary>
        /// Creates an independent cursor over the complete encoded payload.<br/>
        /// The returned segment is a short-lived pooled wrapper and should be disposed when the caller has finished reading it.<br/>
        /// Use <see cref="RawMemory"/> or <see cref="RawSpan"/> when cursor semantics are not required.<br/>
        /// </summary>
        public BufferStream RawBytes { get => stream.Segment(0); }

        /// <summary>
        /// Exposes the complete encoded payload as a read-only memory view without creating a segment cursor or copying bytes.<br/>
        /// The view is valid only while this instance remains alive and its backing payload has not been rebound.<br/>
        /// Use <see cref="RawBytes"/> when an independently positioned <see cref="BufferStream"/> is required.<br/>
        /// </summary>
        public ReadOnlyMemory<byte> RawMemory => stream.AsReadOnlyMemory;

        /// <summary>
        /// Exposes the complete encoded payload as a read-only span without creating a segment cursor or copying bytes.<br/>
        /// The span cannot escape the caller's current synchronous scope and therefore naturally follows the backing payload lifetime.<br/>
        /// Use <see cref="RawBytes"/> when an independently positioned <see cref="BufferStream"/> is required.<br/>
        /// </summary>
        public ReadOnlySpan<byte> RawSpan => stream.AsReadOnlySpan;

        /// <summary>
        /// Creates a shallow clone that reuses discovered name entries while giving each caller an independent cursor and materialization cache.<br/>
        /// Clones get a fresh <c>refCache</c> and <see cref="BufferStream"/> over the same payload bytes.<br/>
        /// </summary>
        /// <returns>A new <see cref="InhetoBinary"/> backed by the same payload with its own stream position.<br/></returns>
        public InhetoBinary ShallowClone()
        {
            var cloneStream = new BufferStream(stream.AsReadOnlyMemory, stream.StringEncoding);
            var clone = new InhetoBinary(cloneStream, serializationOptions, deserializationOptions)
            {
                refCache = new Dictionary<uint, object>(),
                materializationContext = materializationContext
            };

            CloneResolvedNameEntryCacheTo(clone);

            return clone;
        }

        /// <summary>
        /// Clones a value when it is mutable so the cache stays pristine and callers get isolated instances.<br/>
        /// Immutable/value types are returned as-is.<br/>
        /// </summary>
        private static T CloneIfMutable<T>(T value)
        {
            if (value is null) return value!;

            object result = value switch
            {
                // Compatible signed/enum array casts must not turn those arrays into actual byte[] clones.
                byte[] ba when ba.GetType() == typeof(byte[]) => ba.ToArray(),
                Array arr => arr.Clone()!,
                Memory<byte> mem => mem.ToArray().AsMemory(),
                ReadOnlyMemory<byte> rom => new ReadOnlyMemory<byte>(rom.ToArray()),
                System.Collections.BitArray bits => new System.Collections.BitArray(bits),
                System.Collections.Specialized.NameValueCollection nvc => new System.Collections.Specialized.NameValueCollection(nvc),
                System.Collections.Specialized.StringCollection sc => CloneStringCollection(sc),
                System.Text.StringBuilder sb => new System.Text.StringBuilder(sb.ToString()),
                System.IO.MemoryStream ms => new System.IO.MemoryStream(ms.ToArray(), writable: false),
                System.Collections.IDictionary dict when dict.GetType().IsGenericType => CloneDictionary(dict),
                System.Collections.IList list when list.GetType().IsGenericType => CloneList(list),
                _ => value!
            };

            return (T)result;

            static System.Collections.Specialized.StringCollection CloneStringCollection(System.Collections.Specialized.StringCollection sc)
            {
                var copy = new System.Collections.Specialized.StringCollection();
                foreach (var item in sc) copy.Add(item);
                return copy;
            }

            static object CloneList(System.Collections.IList list)
            {
                if (TryCloneKnownList(list, out var preserved)) return preserved!;
                var elemType = list.GetType().GetGenericArguments()[0];
                var listType = typeof(List<>).MakeGenericType(elemType);
                var copy = (System.Collections.IList)Activator.CreateInstance(listType)!;
                foreach (var item in list) copy.Add(item);
                return copy;
            }

            static object CloneDictionary(System.Collections.IDictionary dict)
            {
                if (TryCloneKnownDictionary(dict, out var preserved)) return preserved!;
                var args = dict.GetType().GetGenericArguments();
                var dictType = typeof(Dictionary<,>).MakeGenericType(args[0], args[1]);
                var copy = (System.Collections.IDictionary)Activator.CreateInstance(dictType)!;
                foreach (System.Collections.DictionaryEntry kv in dict) copy.Add(kv.Key, kv.Value);
                return copy;
            }
        }

        /// <summary>
        /// Reuses array, string-list, NameValueCollection, StringCollection, MemoryStream and StringBuilder referents within an explicit materialization operation.<br/>
        /// Array aliases retain their actual output instance; marker-aware callers separately copy DuplicateValue results.<br/>
        /// Other value families and standalone reads retain their existing mutable-copy isolation.<br/>
        /// </summary>
        /// <typeparam name="T">Cached output value or projection type.<br/></typeparam>
        /// <param name="key">Resolved physical referent header index.<br/></param>
        /// <param name="factory">Constructs and fills the missing value.<br/></param>
        /// <param name="preserveIdentity">True only for collection reconstruction inside an explicit operation, where copying would break owner references.<br/></param>
        /// <returns>The operation's referent or the established isolated mutable copy.<br/></returns>
        private T GetOrAddCached<T>(uint key, Func<uint, T> factory, bool preserveIdentity = false)
        {
            if (RefCache.TryGetValue(key, out var existing) && existing is T typed)
                return materializationOperationDepth != 0 && (preserveIdentity || typed is Array or List<string> or NameValueCollection or StringCollection or MemoryStream or StringBuilder)
                    ? typed : CloneIfMutable(typed);

            var created = factory(key);
            if (materializationOperationDepth != 0 && (preserveIdentity || created is Array or List<string> or NameValueCollection or StringCollection or MemoryStream or StringBuilder))
            {
                RefCache[key] = created!;
                return created;
            }
            var stored = CloneIfMutable(created);
            RefCache[key] = stored!;
            return CloneIfMutable(stored);
        }








        //======  METHODS  ======
        /// <summary>
        /// Fills selected destination members through cached compiled accessors and existing shape readers.<br/>
        /// Retains the first successfully filled reference for later aliases within the operation; distinct initialized referents are filled temporarily.<br/>
        /// Exact logical member paths win. With name aliases configured, a missed member may fall back to its physical parent's namespace.<br/>
        /// Failed publications are removed, temporary prior entries are restored, and operation completion releases retained values.<br/>
        /// </summary>
        /// <param name="dzOptions">Current member policy, aliases and hooks.<br/></param>
        /// <param name="parentPath">Logical or alias-resolved parent path retained for requested-member precedence.<br/></param>
        /// <param name="obj">Existing destination object or box filled in place.<br/></param>
        /// <param name="useCoercion">Existing scalar conversion policy.<br/></param>
        /// <param name="throwOnTypeMismatch">Existing type-mismatch behavior.<br/></param>
        /// <param name="sourceIndex">Optional physical ordinary-parent header index for cold projection fallback; zero disables it.<br/></param>
        /// <param name="selectedMember">Optional exact cached member segment for on-demand canonical hydration; null fills the ordinary complete plan.<br/></param>
        /// <returns>The populated destination, including updated boxed value types.<br/></returns>
        object doPropsAndFields(DeserializationOptions dzOptions, string parentPath, ref object obj, bool useCoercion = false, bool throwOnTypeMismatch = true, uint sourceIndex = 0, string? selectedMember = null)
        {
            _nameEntryCacheSuppressionDepth++;
            try
            {
                var tType = obj.GetType();
                string? physicalParentPath = null;
                bool physicalParentChecked = false;

                foreach (MaterializationMember materializationMember in GetMaterializationMembers(tType, dzOptions.MemberTypes))
                {
                if (selectedMember is not null && !StringComparer.Ordinal.Equals(selectedMember, materializationMember.PathSegment)) continue;
                var prop = materializationMember.Member;
                var requestedPropPath = parentPath.Length == 0
                    ? materializationMember.PathSegment
                    : string.Concat(parentPath, materializationMember.PathSegment);
                if (dzOptions.ExcludedMembers?.Contains(requestedPropPath) == true)
                    continue;
                var propType = materializationMember.MemberType;
                var pTypeIsEnum = materializationMember.IsEnum;
                var projectedTypeInfo = materializationMember.TypeInfo;
                if (!prop.CanWrite && !projectedTypeInfo.IsComplex && !projectedTypeInfo.IsCollection && !projectedTypeInfo.IsArray && projectedTypeInfo.BaseType != InhetoBaseTypes.ListString) continue;
                var entry = GetNameEntryFromPropPath(
                    requestedPropPath,
                    dzOptions,
                    out string propPath,
                    cacheResolution: false);
                if (entry.IsEmpty && sourceIndex != 0 && dzOptions.Aliases.HasEntries)
                {
                    // Only a missed projected member needs the physical parent's alias namespace.
                    // Keep requested-path precedence and compute this cold fallback at most once per parent.
                    if (!physicalParentChecked)
                    {
                        physicalParentChecked = true;
                        string physicalPath = NameHeaderEntry.CreateBorrowed(stream, sourceIndex).PropPath;
                        if (!StringComparer.Ordinal.Equals(physicalPath, parentPath)) physicalParentPath = physicalPath;
                    }
                    if (physicalParentPath is not null)
                        entry = GetNameEntryFromPropPath(string.Concat(physicalParentPath, materializationMember.PathSegment),
                            dzOptions, out propPath, cacheResolution: false);
                }
                if (entry.IsEmpty) continue;
                var originalBaseType = entry.Type.BaseType;
                if (entry.Kind == InhetoKindMasks.InhetoBaseType &&
                    entry.Type.BaseType is InhetoBaseTypes.DuplicateRef or InhetoBaseTypes.DuplicateValue)
                {
                    entry = NameHeaderEntry.CreateBorrowed(stream, entry.ValueOffset, entry.Name);
                }
                IAccessors acc = materializationMember.Accessors;

                if (entry.Kind == InhetoKindMasks.InhetoBaseType &&
                    entry.Type.BaseType is InhetoBaseTypes.CustomProp or InhetoBaseTypes.CustomType &&
                    originalBaseType != InhetoBaseTypes.DuplicateValue &&
                    TryReadCustomValue(entry, requestedPropPath, propPath, originalBaseType == InhetoBaseTypes.DuplicateRef, propType, dzOptions, out var customValue))
                {
                    if (acc is null) throw new InvalidOperationException($"No member accessor is available for custom value '{propPath}'.");
                    acc.SetValue(ref obj, customValue);
                    continue;
                }

                // Explicit Null is a value, unlike an omitted header. Do not activate/fill
                // a reference destination for it, or invoke a registered custom decoder.
                // Non-nullable value projections retain their existing typed-reader policy.
                if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Null &&
                    (!propType.IsValueType || Nullable.GetUnderlyingType(propType) is not null))
                {
                    if (acc is not null && !acc.ReadOnly) acc.SetValue(ref obj, null);
                    continue;
                }

                if (projectedTypeInfo.IsArray && IsComplexArrayShape(propType, entry, dzOptions.MemberTypes))
                {
                    if (acc is null) throw new InvalidOperationException($"No member accessor is available for complex array '{propPath}'.");
                    if (!acc.ReadOnly) acc.SetValue(ref obj, ReadComplexArray(propType, entry, propPath, dzOptions));
                    continue;
                }

                if (projectedTypeInfo.IsArray && HasNullableArrayLeaf(propType) &&
                    entry.Kind == InhetoKindMasks.InhetoPromotedType &&
                    entry.Type.PromotedType is InhetoPromotedTypes.Array or InhetoPromotedTypes.ArrayMD)
                {
                    if (acc is null)
                        throw new InvalidOperationException($"No member accessor is available for nullable array '{propPath}'.");
                    Array nullableValue;
                    if (materializationOperationDepth != 0 && refCache is not null &&
                        refCache.TryGetValue(entry.Index, out var cachedNullable) && cachedNullable is Array cachedArray &&
                        propType.IsInstanceOfType(cachedArray))
                        nullableValue = cachedArray;
                    else
                    {
                        nullableValue = ReadNullableArray(propType, entry, propPath, dzOptions);
                        if (materializationOperationDepth != 0) RefCache[entry.Index] = nullableValue;
                    }
                    acc.SetValue(ref obj, materializationOperationDepth != 0 && originalBaseType == InhetoBaseTypes.DuplicateValue
                        ? CloneIfMutable(nullableValue) : nullableValue);
                    continue;
                }

                if (entry.Kind == InhetoKindMasks.InhetoBaseType &&
                    entry.Type.BaseType == InhetoBaseTypes.CustomProp &&
                    (dzOptions.MemberDeserializers.TryGetValue(requestedPropPath, out var memberDeserializer) ||
                     (!StringComparer.Ordinal.Equals(requestedPropPath, propPath) &&
                      dzOptions.MemberDeserializers.TryGetValue(propPath, out memberDeserializer))))
                {
                    stream.Position = entry.ValueOffset;
                    acc.SetValue(ref obj, memberDeserializer.Invoke(stream.ReadBytesWithByteLength()));
                    continue;
                }

                if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.CustomType)
                {
                    stream.Position = entry.ValueOffset;
                    var serializedType = Type.GetType(stream.ReadString() ?? throw new InvalidDataException("Missing custom payload type name."));
                    if (serializedType is not null &&
                        (propType.IsAssignableFrom(serializedType) || Nullable.GetUnderlyingType(propType) == serializedType) &&
                        dzOptions.TypeDeserializers.TryGetValue(serializedType, out var typeDeserializer))
                    {
                        acc.SetValue(ref obj, typeDeserializer.Invoke(stream.ReadBytesWithByteLength()));
                        continue;
                    }
                }

                if (entry.Kind == InhetoKindMasks.InhetoBaseType &&
                    entry.Type.BaseType is InhetoBaseTypes.CustomProp or InhetoBaseTypes.CustomType)
                {
                    if (acc is not null && !acc.ReadOnly)
                        acc.SetValue(ref obj, ReadCustomFallback(entry, propType, requestedPropPath));
                    continue;
                }

                if (entry.Kind == InhetoKindMasks.InhetoPromotedType && entry.Type.PromotedType == InhetoPromotedTypes.Enumerable &&
                    TryGetEnumerableCollectionElementType(propType, out var enumerableElementType))
                {
                    var suppliedEnumerable = acc.GetValue(obj);
                    if (suppliedEnumerable is null && acc.ReadOnly) continue;
                    var enumerableValue = ReadEnumerableCollection(propType, enumerableElementType, suppliedEnumerable, entry,
                        propPath, requestedPropPath, dzOptions);
                    if (!acc.ReadOnly) acc.SetValue(ref obj, enumerableValue);
                    continue;
                }

                // A known complex reference can reuse the ordinary referent-fill path even for an object slot.
                if (propType == typeof(object) && originalBaseType == InhetoBaseTypes.DuplicateRef &&
                    entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.ComplexType &&
                    !(entry.Index == 1 && activeComplexRoot is not null) &&
                    (refCache is null || !refCache.ContainsKey(entry.Index)))
                    TryHydrateCanonicalMember(entry.Index, dzOptions, obj, parentPath, sourceIndex);
                if (propType == typeof(object) && !(originalBaseType == InhetoBaseTypes.DuplicateRef &&
                    entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.ComplexType &&
                    ((entry.Index == 1 && activeComplexRoot is not null) ||
                     (refCache is not null && refCache.ContainsKey(entry.Index)))))
                {
                    // Container-owned children can point back to the already published container through an object slot.
                    // Preserve supplied slots; a missing writable slot can directly share the operation's referent.
                    if (originalBaseType == InhetoBaseTypes.DuplicateRef &&
                        (entry.Kind == InhetoKindMasks.InhetoCollectionType ||
                         entry.Kind == InhetoKindMasks.InhetoPromotedType && entry.Type.PromotedType is InhetoPromotedTypes.Array or InhetoPromotedTypes.ArrayMD or InhetoPromotedTypes.Enumerable) &&
                        refCache is not null && refCache.TryGetValue(entry.Index, out var containerReference) &&
                        acc.GetValue(obj) is null && !acc.ReadOnly)
                    {
                        acc.SetValue(ref obj, containerReference);
                        continue;
                    }
                    acc.SetValue(ref obj, ReadPropInternal(propPath, dzOptions));
                    continue;
                }

                switch (projectedTypeInfo.Kind)
                {
                    case InhetoKindRoute.Base:
                        switch (projectedTypeInfo.BaseType)
                        {
                            case InhetoBaseTypes.Boolean:
                                SetPropFieldBoolean(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Char:
                                SetPropFieldChar(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Rune:
                                SetPropFieldRune(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.String:
                                SetPropFieldString(obj, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.SByte:
                                SetPropFieldSByte(obj, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Byte:
                                SetPropFieldByte(obj, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Int16:
                                SetPropFieldInt16(obj, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.UInt16:
                                SetPropFieldUInt16(obj, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Int32:
                                SetPropFieldInt32(obj, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.UInt32:
                                SetPropFieldUInt32(obj, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Int64:
                                SetPropFieldInt64(obj, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.UInt64:
                                SetPropFieldUInt64(obj, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Half:
                                SetPropFieldHalf(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Single:
                                SetPropFieldSingle(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Double:
                                SetPropFieldDouble(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Decimal:
                                SetPropFieldDecimal(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.DateOnly:
                                SetPropFieldDateOnly(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.DateTime:
                                SetPropFieldDateTime(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.DateTimeOffset:
                                SetPropFieldDateTimeOffset(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.TimeOnly:
                                SetPropFieldTimeOnly(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.TimeSpan:
                                SetPropFieldTimeSpan(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Guid:
                                SetPropFieldGuid(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Int128:
                                SetPropFieldInt128(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.UInt128:
                                SetPropFieldUInt128(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Version:
                                SetPropFieldVersion(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Uri:
                                SetPropFieldUri(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.Vector2:
                                SetPropFieldVector2(obj, propPath, entry, acc);
                                break;
                            case InhetoBaseTypes.Vector3:
                                SetPropFieldVector3(obj, propPath, entry, acc);
                                break;
                            case InhetoBaseTypes.Vector4:
                                SetPropFieldVector4(obj, propPath, entry, acc);
                                break;
                            case InhetoBaseTypes.ComplexNumeric:
                                SetPropFieldComplex(obj, propPath, entry, acc);
                                break;
                            case InhetoBaseTypes.Quaternion:
                                SetPropFieldQuaternion(obj, propPath, entry, acc);
                                break;
                            case InhetoBaseTypes.Plane:
                                SetPropFieldPlane(obj, propPath, entry, acc);
                                break;
                            case InhetoBaseTypes.Matrix3x2:
                                SetPropFieldMatrix3x2(obj, propPath, entry, acc);
                                break;
                            case InhetoBaseTypes.Matrix4x4:
                                SetPropFieldMatrix4x4(obj, propPath, entry, acc);
                                break;
                            case InhetoBaseTypes.BigInteger:
                                SetPropFieldBigInteger(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.ByteArray:
                                SetPropFieldByteArray(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoBaseTypes.ListString:
                                SetPropFieldListString(obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc, dzOptions);
                                break;
                            case InhetoBaseTypes.ComplexType:
                                var pValue = acc.GetValue(obj);

                                // A null destination can close a back-reference to an object already
                                // being filled. An independently initialized destination remains its own
                                // object and is filled separately, preserving developer-owned topology.
                                object? activeValue = null;
                                bool hasActiveValue = refCache is not null && refCache.TryGetValue(entry.Index, out activeValue);
                                if (!hasActiveValue && (pValue is not null || !acc.ReadOnly) && originalBaseType == InhetoBaseTypes.DuplicateRef &&
                                    !(entry.Index == 1 && activeComplexRoot is not null))
                                {
                                    TryHydrateCanonicalMember(entry.Index, dzOptions, obj, parentPath, sourceIndex);
                                    hasActiveValue = refCache is not null && refCache.TryGetValue(entry.Index, out activeValue);
                                }
                                // A declined canonical activation is intentional, not an unavailable destination.
                                // Supplied objects still retain their independent fill contract.
                                if (hasActiveValue && activeValue is null && pValue is null) continue;
                                if (activeValue is null && entry.Index == 1) activeValue = activeComplexRoot;
                                if (!propType.IsValueType && activeValue is not null && propType.IsInstanceOfType(activeValue) &&
                                    (pValue is null || ReferenceEquals(pValue, activeValue)))
                                {
                                    if (pValue is null && !acc.ReadOnly) acc.SetValue(ref obj, activeValue);
                                    continue;
                                }

                                if (pValue is null)
                                {
                                    if (acc.ReadOnly) continue;

                                    if (dzOptions.TryGetActivator(propType, out var act))
                                        pValue = act(CreateActivatorContext(propPath))!;
                                    else
                                        pValue = Activator.CreateInstance(propType);

                                    // A null activation result declines this destination's rehydration.
                                    // Do not assign, publish or walk descendants when no instance was supplied.
                                    if (pValue is null)
                                    {
                                        if (!propType.IsValueType) RefCache[entry.Index] = null!;
                                        continue;
                                    }
                                    acc.SetValue(ref obj, pValue);
                                }

                                bool publishMember = !propType.IsValueType && pValue is not null;
                                object? priorMember = null;
                                bool hadMember = publishMember && RefCache.TryGetValue(entry.Index, out priorMember);
                                // The fast root materializer keeps its first referent outside the dictionary.
                                // Treat that root as a prior publication when temporarily filling an initialized root alias.
                                if (publishMember && !hadMember && entry.Index == 1 && activeComplexRoot is not null)
                                {
                                    priorMember = activeComplexRoot;
                                    hadMember = true;
                                }
                                if (publishMember) RefCache[entry.Index] = pValue!;
                                bool memberCompleted = false;
                                try
                                {
                                    pValue = doPropsAndFields(dzOptions, propPath, ref pValue!, useCoercion, throwOnTypeMismatch, entry.Index);
                                    memberCompleted = true;
                                }
                                finally
                                {
                                    if (publishMember)
                                    {
                                        // Keep the first completed referent until the operation ends so later aliases can join it.
                                        // A distinct supplied destination is temporary: restore the prior referent after filling it.
                                        if (hadMember) RefCache[entry.Index] = priorMember!;
                                        else if (!memberCompleted) RefCache.Remove(entry.Index);
                                    }
                                }

                                if (propType.IsValueType)
                                    acc.SetValue(ref obj, pValue);
                                break;
                        }
                        break;
                    case InhetoKindRoute.Promoted:
                        switch (projectedTypeInfo.PromotedType)
                        {
                            case InhetoPromotedTypes.Array:
                                // The internal fixed maps cannot bypass the array resolver's element metadata.
                                var iet = InhetoTypeResolver.GetInhetoTypeInfo(projectedTypeInfo.ElementType!, dzOptions.MemberTypes);
                                SetPropFieldArray(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, iet, entry, acc, dzOptions);
                                break;
                            case InhetoPromotedTypes.ArrayMD:
                                // Array/ArrayMD plans retain the complete resolver result, including ElementType.
                                var ietMD = InhetoTypeResolver.GetInhetoTypeInfo(projectedTypeInfo.ElementType!, dzOptions.MemberTypes);
                                SetPropFieldArrayMD(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, ietMD, entry, acc, dzOptions);
                                break;
                            case InhetoPromotedTypes.CultureInfo:
                                SetPropFieldCultureInfo(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.SecureString:
                                SetPropFieldSecureString(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.Enum:
                                SetPropFieldEnum(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.IPAddress:
                                SetPropFieldIPAddress(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.IPEndPoint:
                                SetPropFieldIPEndPoint(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.MailAddress:
                                SetPropFieldMailAddress(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.MemoryByte:
                                SetPropFieldMemoryByte(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.ReadOnlyMemoryByte:
                                SetPropFieldReadOnlyMemoryByte(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.MemoryStream:
                                SetPropFieldMemoryStream(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.NameValueCollection:
                                SetPropFieldNameValueCollection(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.TimeZoneInfo:
                                SetPropFieldTimeZoneInfo(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.Regex:
                                SetPropFieldRegex(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.StringBuilder:
                                SetPropFieldStringBuilder(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.Type:
                                SetPropFieldSystemType(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.StringCollection:
                                SetPropFieldStringCollection(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc);
                                break;
                            case InhetoPromotedTypes.Enumerable:
                                SetPropFieldEnumerable(ref obj, useCoercion, throwOnTypeMismatch, propPath, projectedTypeInfo, entry, acc, dzOptions);
                                break;
                        }
                        break;
                    case InhetoKindRoute.Collection:
                        {
                            var propValue = acc.GetValue(obj);

                            // A canonical branch can have filled this exact destination ahead of the normal member pass.
                            // Do not append its entries twice. Distinct supplied destinations retain independent filling.
                            if (refCache is not null && refCache.TryGetValue(entry.Index, out var scheduledCollection))
                            {
                                if (ReferenceEquals(propValue, scheduledCollection)) continue;
                                if (propValue is null && !acc.ReadOnly && propType.IsInstanceOfType(scheduledCollection))
                                {
                                    acc.SetValue(ref obj, scheduledCollection);
                                    continue;
                                }
                            }

                            if (propValue is null)
                            {

                                if (acc.ReadOnly) continue;

                                object? comparer = null;
                                comparer = GetComparerIfAny(propPath, dzOptions, tType, entry);

                                if (dzOptions.TryGetActivator(propType, out var act))
                                {
                                    propValue = act(CreateActivatorContext(propPath, comparer))!;
                                    if (propValue is null)
                                    {
                                        if (selectedMember is not null) RefCache[entry.Index] = null!;
                                        continue;
                                    }
                                }
                                else
                                {
                                    var activator = dzOptions.ActivatorWithComparerHelper.GetActivatorDelegate(propType); // use the cached activator
                                    propValue = activator(CreateActivatorContext(propPath, comparer));
                                }
                                acc.SetValue(ref obj, propValue);
                            }

                            // Elements and declared members can both reference their containing collection.
                            // A distinct supplied destination is published only for its own fill, then the first referent is restored.
                            bool publishCollection = entry.Kind == InhetoKindMasks.InhetoCollectionType || selectedMember is not null;
                            object? priorCollection = null;
                            bool hadCollection = publishCollection && RefCache.TryGetValue(entry.Index, out priorCollection);
