                                projectedTypeInfo.ElementType is Type dictionaryValueType &&
                                (!InhetoSerializer.IsSafeKeyType(dictionaryKeyType) ||
                                 !InhetoBaseTypesMap.ContainsKey(dictionaryKeyType.TypeHandle) ||
                                 (!InhetoBaseTypesMap.ContainsKey(dictionaryValueType.TypeHandle) &&
                                  !InhetoPromotedTypesMap.ContainsKey(dictionaryValueType.TypeHandle))) &&
