        internal void FillBigIntegerList(NameHeaderEntry entry, IEnumerable? propValue, bool useCoercion, bool throwOnTypeMismatch)
        {
            if (!EnumerableMutator.TryGetMutator(propValue, out var mutator)) return;
            if (useCoercion && HasCustomScalarProjection(entry, InhetoBaseTypes.BigInteger))
            {
                for (int i = mutator.ReverseEncodedOrder ? checked((int)entry.ValueOffset) - 1 : 0,
                    slotEnd = mutator.ReverseEncodedOrder ? -1 : checked((int)entry.ValueOffset), slotStep = mutator.ReverseEncodedOrder ? -1 : 1;
                    i != slotEnd; i += slotStep)
                    mutator.Add(propValue, ReadMaterializedAs<BigInteger>($"{entry.PropPath}#{i}", materializationOptions ?? deserializationOptions));
                return;
            }
            switch (entry.Type.CollectionInfo.ValueType.BaseType)
            {
                case InhetoBaseTypes.BigInteger:
                    for (int i = mutator.ReverseEncodedOrder ? checked((int)entry.ValueOffset) - 1 : 0,
                        slotEnd = mutator.ReverseEncodedOrder ? -1 : checked((int)entry.ValueOffset), slotStep = mutator.ReverseEncodedOrder ? -1 : 1;
                        i != slotEnd; i += slotStep)
                    {
                        mutator.Add(propValue, ReadMaterializedBigInteger($"{entry.PropPath}#{i}") ?? default);
                    }
                    break;
            }
        }

        internal void FillBooleanList(NameHeaderEntry entry, IEnumerable? propValue, bool useCoercion, bool throwOnTypeMismatch)
        {
            if (!EnumerableMutator.TryGetMutator(propValue, out var mutator)) return;
            if (useCoercion && HasCustomScalarProjection(entry, InhetoBaseTypes.Boolean))
            {
                for (int i = mutator.ReverseEncodedOrder ? checked((int)entry.ValueOffset) - 1 : 0,
                    slotEnd = mutator.ReverseEncodedOrder ? -1 : checked((int)entry.ValueOffset), slotStep = mutator.ReverseEncodedOrder ? -1 : 1;
                    i != slotEnd; i += slotStep)
                    mutator.Add(propValue, ReadMaterializedAs<bool>($"{entry.PropPath}#{i}", materializationOptions ?? deserializationOptions));
                return;
            }
            switch (entry.Type.CollectionInfo.ValueType.BaseType)
            {
                case InhetoBaseTypes.Boolean:
                    for (int i = mutator.ReverseEncodedOrder ? checked((int)entry.ValueOffset) - 1 : 0,
                        slotEnd = mutator.ReverseEncodedOrder ? -1 : checked((int)entry.ValueOffset), slotStep = mutator.ReverseEncodedOrder ? -1 : 1;
                        i != slotEnd; i += slotStep)
                    {
                        mutator.Add(propValue, ReadMaterializedBoolean($"{entry.PropPath}#{i}") ?? default);
                    }
                    break;
                case InhetoBaseTypes.SByte:
                    if (!useCoercion)
                        throw new InvalidDataException($"Type mismatch at {entry.PropPath}: expected array of bool, got array of {entry.Type.CollectionInfo.ValueType.BaseType}.");

                    for (int i = mutator.ReverseEncodedOrder ? checked((int)entry.ValueOffset) - 1 : 0,

                        slotEnd = mutator.ReverseEncodedOrder ? -1 : checked((int)entry.ValueOffset), slotStep = mutator.ReverseEncodedOrder ? -1 : 1;

                        i != slotEnd; i += slotStep)
                    {
                        mutator.Add(propValue, (ReadMaterializedSByte($"{entry.PropPath}#{i}") ?? default) == 0 ? false : true);
