        /// <summary>
        /// Fills enum collection slots using their complete child headers and the destination CLR element type.<br/>
        /// Ordinary enum collections have a complex-element parent descriptor; each child carries its numeric enum representation.<br/>
        /// The shared filler binds a typed loop once per element type, retains hooks and checked numeric coercion,
        /// and avoids element boxing for ICollection destinations.<br/>
        /// The generic integer is only the shape-only fallback; it must not be mistaken for an enum CLR type.<br/>
        /// </summary>
        /// <typeparam name="EnumUnderlying">Caller-selected integer representation used only when the destination has no element metadata.<br/></typeparam>
        /// <param name="entry">Collection header with encoded child count and progressive property path.<br/></param>
        /// <param name="propValue">Optional mutable destination; IList is not required and existing contents are retained.<br/></param>
        /// <param name="useCoercion">Allows a parent-declared numeric representation to differ from the destination.<br/></param>
        /// <param name="throwOnTypeMismatch">Throws for a disallowed parent representation change instead of leaving the target unchanged.<br/></param>
        internal void FillEnumList<EnumUnderlying>(NameHeaderEntry entry, IEnumerable? propValue, bool useCoercion, bool throwOnTypeMismatch) where EnumUnderlying : INumber<EnumUnderlying>
        {
            if (propValue is null || !EnumerableMutator.TryGetMutator(propValue, out _)) return;
            var destinationType = InhetoTypeResolver.GetInhetoTypeInfo(propValue.GetType()).ElementType ?? typeof(EnumUnderlying);
            var numericType = destinationType.IsEnum ? destinationType.GetEnumUnderlyingType() : destinationType;
            var sourceType = entry.Type.CollectionInfo.ValueType;
            if (!useCoercion && sourceType.Kind == InhetoKindMasks.InhetoPromotedType &&
                sourceType.PromotedType == InhetoPromotedTypes.Enum &&
                InhetoBaseTypesMap.TryGetValue(numericType.TypeHandle, out var destinationMarker) &&
                sourceType.EnumType != destinationMarker)
            {
                if (throwOnTypeMismatch)
                    throw new AmbiguousMatchException($"Type mismatch at {entry.PropPath}: expected list of {destinationType.Name}, got list of {sourceType}.");
                return;
            }
            FillCollectionElements(destinationType, propValue, entry.ValueOffset, entry.PropPath,
                materializationOptions ?? deserializationOptions);
        }

