        internal void FillVersionList(NameHeaderEntry entry, IEnumerable? propValue, bool useCoercion, bool throwOnTypeMismatch)
        {
            if (!EnumerableMutator.TryGetMutator(propValue, out var mutator)) return;
            switch (entry.Type.CollectionInfo.ValueType.BaseType)
            {
                case InhetoBaseTypes.Version:
                    for (int i = mutator.ReverseEncodedOrder ? checked((int)entry.ValueOffset) - 1 : 0,
                        slotEnd = mutator.ReverseEncodedOrder ? -1 : checked((int)entry.ValueOffset), slotStep = mutator.ReverseEncodedOrder ? -1 : 1;
                        i != slotEnd; i += slotStep)
                    {
                        mutator.Add(propValue, ReadVersionCore($"{entry.PropPath}#{i}") ?? default);
                    }
                    break;
                case InhetoBaseTypes.String:
                    if (!useCoercion)
                        if (throwOnTypeMismatch)
                            throw new AmbiguousMatchException($"Type mismatch at {entry.PropPath}: expected list of Version, got list of {entry.Type.CollectionInfo.ValueType.BaseType}.");
                        else
                            return;
                    for (int i = mutator.ReverseEncodedOrder ? checked((int)entry.ValueOffset) - 1 : 0,
                        slotEnd = mutator.ReverseEncodedOrder ? -1 : checked((int)entry.ValueOffset), slotStep = mutator.ReverseEncodedOrder ? -1 : 1;
                        i != slotEnd; i += slotStep)
                    {
                        var text = ReadStringCore($"{entry.PropPath}#{i}");
                        mutator.Add(propValue, text is null ? null : new Version(text));
                    }
                    break;
            }
        }

        //======  METHODS  ======
        private Dictionary<string, NameHeaderNavigation>? allNames;
        /// <summary>
        /// Captures the complete name/path navigation map without decoding or retaining recursive native type descriptors.<br/>
        /// The map contains only immutable names, paths and numeric indices; public AllNames still returns an independent list.<br/>
        /// Publication occurs only after a complete successful scan, so malformed input cannot cache a partial map.<br/>
        /// </summary>
        /// <returns>The payload-local navigation map, reused until this reader is rebound.<br/></returns>
        internal Dictionary<string, NameHeaderNavigation> GetAllNames()
        {
            using var rooted = new LiteralValueReadScope(this, 0, null);
            if (allNames != null) return allNames;
            var names = new Dictionary<string, NameHeaderNavigation>();
            uint index = 1;
            while (index != 0)
            {
                var entry = NameHeaderEntry.ReadNavigation(stream, index, out uint next);
                if (next == 0) break;
                string path = entry.PropPath;
                if (!names.TryAdd(path, entry) && TryFindCompiledNameEntry(path, out uint selectedIndex) && selectedIndex != 0)
                    names[path] = NameHeaderEntry.ReadNavigation(stream, selectedIndex, out _);
                index = next;
            }
            return allNames = names;
        }

        /// <summary>
        /// Gets a newly allocated list of unique indexed property-path strings; repeated calls allocate another list.<br/>
        /// When literal dictionary keys shadow a shorter traversal, the shared string follows most-specific key lookup.<br/>
        /// This is not a separate identifier for every physical graph location when two locations produce identical text.<br/>
        /// </summary>
        public List<string> AllNames
        {
            get { return GetAllNames().Keys.ToList(); }
        }

        private NameHeaderEntry GetNameEntryFromPropPath(string propPath, bool cacheResolution = true)
        {
            propPath ??= "";
            PreparedInhetoPath preparedPath = GetPreparedPath(propPath);
            return GetNameEntryFromPropPath(preparedPath, cacheResolution);
        }

        /// <summary>
        /// Resolves an exact prepared physical path without repeating the shared path-registry lookup in each payload reader.<br/>
        /// The payload-local cache retains only the plan token and names-header entry index; a rich borrowed entry is constructed only for callers that need its type or value metadata.<br/>
        /// </summary>
        /// <param name="preparedPath">Immutable physical path plan prepared before the payload loop.<br/></param>
        /// <param name="cacheResolution">Whether stable-token hit or miss results may enter this payload's runtime cache.<br/></param>
        /// <returns>The matching borrowed name-header entry, or an empty entry when the path is absent.<br/></returns>
        private NameHeaderEntry GetNameEntryFromPropPath(PreparedInhetoPath preparedPath, bool cacheResolution = true)
        {
            string propPath = preparedPath.Path;
            if (cacheResolution && TryGetResolvedNameEntry(preparedPath, out uint cachedEntryIndex))
                return cachedEntryIndex == 0
                    ? default
                    : NameHeaderEntry.CreateBorrowed(stream, cachedEntryIndex);

            if (TryFindCompiledNameEntry(preparedPath, out uint compiledEntryIndex))
            {
                NameHeaderEntry compiledEntry = compiledEntryIndex == 0
                    ? default
                    : NameHeaderEntry.CreateBorrowed(stream, compiledEntryIndex);
                if (cacheResolution)
                    CacheResolvedNameEntry(preparedPath, compiledEntryIndex);
                return compiledEntry;
            }

            // Root entry — skip version byte
            var entry = NameHeaderEntry.CreateBorrowed(stream, 1);
            if (string.IsNullOrEmpty(propPath))
            {
                if (cacheResolution)
                    CacheResolvedNameEntry(preparedPath, entry.Index);
                return entry;
            }

            while (entry.Type.BaseType != InhetoBaseTypes.EndOfNamesHeader)
            {
                // NextEntryIndex is the byte immediately following the current entry,
                // so a valid names header is a strictly forward-only chain.
                var next = entry.Next;
                if (next.IsEmpty) break;

                // Cache this entry by its computed full path
                var path = next.PropPath;
                if (cacheResolution)
                    CacheResolvedNameEntry(path, next);

                // Check for match
                if (path == propPath)
                    return next;

                entry = next;
            }

            // If we got here, the propPath was not found.  Cache the not-found entry to avoid further lookups of the same propPath.
            return ResolveReferenceMiss(preparedPath, cacheResolution);
        }

        /// <summary>
        /// Resolves an exact property path through the operation's alias equivalence group.<br/>
        /// The exact requested path always wins, followed by the group's canonical path and remaining aliases.<br/>
        /// </summary>
        private NameHeaderEntry GetNameEntryFromPropPath(
            string propPath,
            DeserializationOptions? dzOptions,
            out string resolvedPath,
            bool cacheResolution = true)
        {
            resolvedPath = propPath ?? string.Empty;
            NameHeaderEntry exact = GetNameEntryFromPropPath(resolvedPath, cacheResolution);
            if (!exact.IsEmpty || dzOptions is null ||
                !dzOptions.Aliases.TryGetGroup(resolvedPath, out PropertyAliasCollection.Group? group, out string suffix))
            {
                return exact;
            }

            string[] paths = group!.Paths;
            for (int index = 0; index < paths.Length; index++)
            {
                string candidate = string.Concat(paths[index], suffix);
                if (StringComparer.Ordinal.Equals(candidate, resolvedPath))
                    continue;
                NameHeaderEntry entry = GetNameEntryFromPropPath(candidate, cacheResolution);
                if (entry.IsEmpty)
                    continue;
                resolvedPath = candidate;
                return entry;
            }
            return default;
        }

        /// <summary>
        /// Resolves the deepest serialized source for a logical property path, including equivalent alias prefixes.<br/>
        /// Exact values outrank prefix materialization; within each class the requested path wins before registered fallbacks.<br/>
        /// </summary>
        private (NameHeaderEntry? Entry, string ResolvedPath, string RemainingPath) GetClosestAliasedNameEntry(
            string propPath,
            DeserializationOptions? dzOptions)
        {
            propPath ??= string.Empty;
            NameHeaderEntry exact = GetNameEntryFromPropPath(propPath);
            if (!exact.IsEmpty)
                return (exact, propPath, string.Empty);

            PropertyAliasCollection.Group? group = null;
            string suffix = string.Empty;
            if (dzOptions is not null)
                dzOptions.Aliases.TryGetGroup(propPath, out group, out suffix);

            if (group is not null)
            {
                string[] paths = group.Paths;
                for (int index = 0; index < paths.Length; index++)
                {
                    string candidate = string.Concat(paths[index], suffix);
                    if (StringComparer.Ordinal.Equals(candidate, propPath))
                        continue;
                    NameHeaderEntry alias = GetNameEntryFromPropPath(candidate);
                    if (!alias.IsEmpty)
                        return (alias, candidate, string.Empty);
                }
            }

            var closest = GetClosestNameEntry(propPath);
            if (closest.Entry is not null && !string.IsNullOrEmpty(closest.Entry.Value.PropPath))
                return (closest.Entry, propPath, closest.RemainingPath);

            if (group is not null)
            {
                string[] paths = group.Paths;
                for (int index = 0; index < paths.Length; index++)
                {
                    string candidate = string.Concat(paths[index], suffix);
                    if (StringComparer.Ordinal.Equals(candidate, propPath))
                        continue;
                    closest = GetClosestNameEntry(candidate);
                    if (closest.Entry is null || string.IsNullOrEmpty(closest.Entry.Value.PropPath))
                        continue;
                    return (closest.Entry, candidate, closest.RemainingPath);
                }
            }
            return (null, propPath, propPath);
        }

        /// <summary>
        /// Attempts to resolve the deepest <see cref="NameHeaderEntry"/> that matches the given property path.
        /// <br/>
        /// Unlike <c>GetNameEntryFromPropPath</c>, this method performs a *progressive prefix match* rather than an exact lookup.
        /// It walks the names header chain, caching each discovered entry, and returns both:
        /// <list type="bullet">
        ///   <item>The <see cref="NameHeaderEntry"/> representing the longest prefix of <paramref name="propPath"/> found in the header chain.</item>
        ///   <item>The remaining unmatched portion of <paramref name="propPath"/>, if any.</item>
        /// </list>
        /// </summary>
        /// <remarks>
        /// <para>
        /// The traversal begins from the root (index 1) and advances via <see cref="NameHeaderEntry.NextEntryIndex"/> until
        /// <see cref="InhetoBaseTypes.EndOfNamesHeader"/> is encountered.
        /// Each entry's <see cref="NameHeaderEntry.PropPath"/> is cached once discovered to accelerate future resolutions.
        /// </para>
        /// <para>
        /// Structural awareness is leveraged through <see cref="NameHeaderEntry.ParentIndex"/>:
        /// when the chain steps to an entry whose <c>ParentIndex</c> is less than the index of the current best match,
        /// traversal short-circuits because subsequent entries cannot belong to the same subtree.
        /// This avoids unnecessary <see cref="string.StartsWith(string, StringComparison)"/> checks and string allocations
        /// for unrelated branches.
        /// </para>
        /// <para>
        /// The cache stores actual entries discovered during traversal, while exact resolution may also cache a confirmed missing path.
        /// Prefix requests do not cache a synthetic partial result; only concrete serialized entries are admitted.
        /// </para>
        /// </remarks>
        /// <param name="propPath">
        /// The property path to resolve.  A dotted syntax is expected (e.g. <c>".ThisProp.ThatProp.Value"</c>).
        /// If empty or null, the root entry is returned.
        /// </param>
        /// <returns>
        /// A <see cref="ValueTuple{T1,T2}"/> where:
        /// <list type="bullet">
        ///   <item><c>Entry</c> — the deepest resolvable <see cref="NameHeaderEntry"/> in the header chain.</item>
        ///   <item><c>RemainingPath</c> — the portion of <paramref name="propPath"/> that could not be matched, beginning with a dot if non-empty.</item>
        /// </list>
        /// </returns>
        /// <example>
        /// Given a names header containing entries up to <c>".ThisProp.ThatProp"</c> and an input path
        /// <c>".ThisProp.ThatProp.Value.More"</c>, this method returns:
        /// <code>
        /// (Entry = { ".ThisProp.ThatProp" }, RemainingPath = ".Value.More")
        /// </code>
        /// </example>
        /// <seealso cref="GetNameEntryFromPropPath(string, bool)"/>
        private (NameHeaderEntry? Entry, string RemainingPath) GetClosestNameEntry(string propPath)
        {
            propPath ??= "";
            if (TryGetResolvedNameEntry(propPath, out NameHeaderEntry cached) && !cached.IsEmpty)
                return (cached, "");

            if (TryResolveLiteralNameEntry(propPath, out var progressive, out int matched, out _))
            {
                string suffix = propPath.Substring(matched);
                if (suffix.Length > 0 && suffix[0] != '.') suffix = "." + suffix;
                return (NameHeaderEntry.CreateBorrowed(stream, progressive.Index), suffix);
            }

            var entry = NameHeaderEntry.CreateBorrowed(stream, 1);
            if (string.IsNullOrEmpty(propPath))
            {
                CacheResolvedNameEntry("", entry);
                return (entry, "");
            }

            NameHeaderEntry? bestMatch = entry;
            string bestMatchPath = "";
            uint bestMatchIndex = 1;

            while (entry.Type.BaseType != InhetoBaseTypes.EndOfNamesHeader)
            {
                var next = entry.Next;
                if (next.IsEmpty) break;

                // Skip if this entry is outside current prefix subtree
                if (next.ParentIndex < bestMatchIndex)
                    break;

                CacheResolvedNameEntry(next.PropPath, next);

                if (propPath.StartsWith(next.PropPath, StringComparison.Ordinal))
                {
                    bestMatch = next;
                    bestMatchPath = next.PropPath;
                    bestMatchIndex = next.Index;

                    if (bestMatchPath == propPath)
                        return (next, "");
                }

                entry = next;
            }

            var remaining = propPath.StartsWith(bestMatchPath, StringComparison.Ordinal)
                ? propPath.Substring(bestMatchPath.Length)
                : propPath;

            if (remaining.Length > 0 && remaining[0] != '.')
                remaining = "." + remaining;

            return (bestMatch, remaining);
        }

        internal Array? ReadArrayOf<ElementType>(string propPath, DeserializationOptions dzOptions, bool useCoercion = false)
        {
            var entry = GetNameEntryFromPropPath(propPath);
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Unknown) return default;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Null) return default;
            bool copy = entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.DuplicateValue;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && (entry.Type.BaseType == InhetoBaseTypes.DuplicateRef || copy))
            {
                entry = NameHeaderEntry.CreateBorrowed(stream, entry.ValueOffset, entry.Name);
            }

            var entryOffset = entry.Index;

            var ret = GetOrAddCached(entryOffset, k =>
            {
                var ret = readArray(propPath, dzOptions, useCoercion, entry);
                return ret;
            });

            return materializationOperationDepth != 0 && copy ? CloneIfMutable(ret) : ret;


            Array? readArray(string propPath, DeserializationOptions dzOptions, bool useCoercion, NameHeaderEntry nvn)
            {
                if (Nullable.GetUnderlyingType(typeof(ElementType)) is not null)
                    return ReadNullableArray(ArrayTypeFromLeaf(typeof(ElementType), nvn), nvn, propPath, dzOptions);
                if (HasNullableArrayLeaf(typeof(ElementType)))
                    return ReadNullableArray(typeof(ElementType).MakeArrayType(), nvn, propPath, dzOptions);
                var acount = nvn.ValueOffset;
                switch (nvn.Type.ArrayInfo.Depth)
                {
                    case 0:
                        // reserved for ByteArray found as base type
                        if (nvn.Kind == InhetoKindMasks.InhetoBaseType && nvn.Type.BaseType == InhetoBaseTypes.ByteArray)
                            return ReadByteArrayCore(propPath);

                        throw new InvalidDataException("Type mismatch at {propPath}: expected array, got non-array.");
                    case 1:
                        if (nvn.Type.ArrayInfo.Rank >= 2)
                            return ReadMDArrayOf<ElementType>(propPath, dzOptions);

                        switch (arrayTypes.GetValueOrDefault(typeof(ElementType).TypeHandle))
                        {
                            case arrayTypesEnum.Default:
                                {
                                    var arrayOfDT = CreateJaggedArray<ElementType>(nvn.Type.ArrayInfo.Depth, (int)acount);
                                    for (int i = 0; i < acount; i++)
                                        arrayOfDT.SetValue(useCoercion ? FastCoerce.Coerce<ElementType>(ReadPropInternal($"{propPath}#{i}", dzOptions) ?? default) : ReadPropInternal($"{propPath}#{i}", dzOptions) ?? default, i);

                                    return arrayOfDT;
                                }
                            case arrayTypesEnum.Bool:
                                {
                                    var arrayOfBo = new bool[acount];
                                    if (!useCoercion)
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfBo[i] = ReadMaterializedBoolean($"{propPath}#{i}") ?? default;
                                        }
                                    else
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfBo[i] = FastCoerce.Coerce<bool>(ReadPropInternal($"{propPath}#{i}", dzOptions));
                                        }
                                    return arrayOfBo;
                                }
                            case arrayTypesEnum.SByte:
                                {
                                    var arrayOfSb = new sbyte[acount];
                                    if (!useCoercion)
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfSb[i] = ReadMaterializedSByte($"{propPath}#{i}") ?? default;
                                        }
                                    else
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfSb[i] = FastCoerce.Coerce<sbyte>(ReadPropInternal($"{propPath}#{i}", dzOptions));
                                        }
                                    return arrayOfSb;
                                }
                            case arrayTypesEnum.Byte:
                                {
                                    var arrayOfB = new byte[acount];
                                    if (!useCoercion)
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfB[i] = ReadMaterializedByte($"{propPath}#{i}") ?? default;
                                        }
                                    else
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfB[i] = FastCoerce.Coerce<byte>(ReadPropInternal($"{propPath}#{i}", dzOptions));
                                        }
                                    return arrayOfB;
                                }
                            case arrayTypesEnum.Int16:
                                {
                                    var arrayOfSh = new short[acount];
                                    if (!useCoercion)
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfSh[i] = ReadMaterializedInt16($"{propPath}#{i}") ?? default;
                                        }
                                    else
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfSh[i] = FastCoerce.Coerce<short>(ReadPropInternal($"{propPath}#{i}", dzOptions));
                                        }
                                    return arrayOfSh;
                                }
                            case arrayTypesEnum.UInt16:
                                {
                                    var arrayOfUSh = new ushort[acount];
                                    if (!useCoercion)
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfUSh[i] = ReadMaterializedUInt16($"{propPath}#{i}") ?? default;
                                        }
                                    else
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfUSh[i] = FastCoerce.Coerce<ushort>(ReadPropInternal($"{propPath}#{i}", dzOptions));
                                        }
                                    return arrayOfUSh;
                                }
                            case arrayTypesEnum.Int32:
                                {
                                    var arrayOfI = new int[acount];
                                    if (!useCoercion)
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfI[i] = ReadMaterializedInt32($"{propPath}#{i}") ?? default;
                                        }
                                    else
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfI[i] = FastCoerce.Coerce<int>(ReadPropInternal($"{propPath}#{i}", dzOptions));
                                        }
                                    return arrayOfI;
                                }
                            case arrayTypesEnum.UInt32:
                                {
                                    var arrayOfUI = new uint[acount];
                                    if (!useCoercion)
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfUI[i] = ReadMaterializedUInt32($"{propPath}#{i}") ?? default;
                                        }
                                    else
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfUI[i] = FastCoerce.Coerce<uint>(ReadPropInternal($"{propPath}#{i}", dzOptions));
                                        }
                                    return arrayOfUI;
                                }
                            case arrayTypesEnum.Int64:
                                {
                                    var arrayOfL = new long[acount];
                                    if (!useCoercion)
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfL[i] = ReadMaterializedInt64($"{propPath}#{i}") ?? default;
                                        }
                                    else
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfL[i] = FastCoerce.Coerce<long>(ReadPropInternal($"{propPath}#{i}", dzOptions));
                                        }
                                    return arrayOfL;
                                }
                            case arrayTypesEnum.UInt64:
                                {
                                    var arrayOfUL = new ulong[acount];
                                    if (!useCoercion)
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfUL[i] = ReadMaterializedUInt64($"{propPath}#{i}") ?? default;
                                        }
                                    else
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfUL[i] = FastCoerce.Coerce<ulong>(ReadPropInternal($"{propPath}#{i}", dzOptions));
                                        }
                                    return arrayOfUL;
                                }
                            case arrayTypesEnum.Int128:
                                {
                                    var arrayOfI128 = new Int128[acount];
                                    if (!useCoercion)
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfI128[i] = ReadMaterializedInt128($"{propPath}#{i}") ?? default;
                                        }
                                    else
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfI128[i] = FastCoerce.Coerce<Int128>(ReadPropInternal($"{propPath}#{i}", dzOptions));
                                        }
                                    return arrayOfI128;
                                }
                            case arrayTypesEnum.UInt128:
                                {
                                    var arrayOfUI128 = new UInt128[acount];
                                    if (!useCoercion)
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfUI128[i] = ReadMaterializedUInt128($"{propPath}#{i}") ?? default;
                                        }
                                    else
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfUI128[i] = FastCoerce.Coerce<UInt128>(ReadPropInternal($"{propPath}#{i}", dzOptions));
                                        }
                                    return arrayOfUI128;
                                }
                            case arrayTypesEnum.Half:
                                {
                                    var arrayOfH = new Half[acount];
                                    if (!useCoercion)
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfH[i] = ReadMaterializedHalf($"{propPath}#{i}") ?? default;
                                        }
                                    else
                                        for (int i = 0; i < acount; i++)
                                        {
                                            arrayOfH[i] = FastCoerce.Coerce<Half>(ReadPropInternal($"{propPath}#{i}", dzOptions));
                                        }
                                    return arrayOfH;
                                }
