        private Array? ReadMDArray(string propPath, DeserializationOptions dzOptions)
        {
            var entry = GetNameEntryFromPropPath(propPath);
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Unknown) return default;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Null) return default;
            bool copy = entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.DuplicateValue;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && (entry.Type.BaseType == InhetoBaseTypes.DuplicateRef || copy))
            {
                entry = NameHeaderEntry.CreateBorrowed(stream, entry.ValueOffset, entry.Name);
            }

            var entryOffset = entry.Index;
            var ret = GetOrAddCached(entryOffset, k =>
            {
                return ReadMDArray(entry, dzOptions);
            });
            return materializationOperationDepth != 0 && copy ? CloneIfMutable(ret) : ret;

        }

        private Array? ReadMDArray(NameHeaderEntry entry, DeserializationOptions dzOptions)
        {
            var sbToken = new StringBuilder();
            var propPath = entry.PropPath;
            var rank = entry.Type.ArrayInfo.Rank;
            var lengths = new int[rank];
            // Dimensions belong to the descriptor; allocate lengths only when constructing this output.
            if (entry.Type.ArrayInfo.ArrayType != InhetoArrayTypes.ArrayMD || entry.CopyLengths(lengths) != rank)
                throw new InvalidDataException($"The multidimensional array metadata at '{propPath}' does not contain rank lengths.");

            switch (entry.Type.ArrayInfo.ElementType.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (entry.Type.ArrayInfo.ElementType.BaseType)
                    {
                        case InhetoBaseTypes.Boolean:
                            return BuildArray<bool>(rank, lengths);
                        case InhetoBaseTypes.SByte:
                            return BuildArray<sbyte>(rank, lengths);
                        case InhetoBaseTypes.Byte:
                            return BuildArray<byte>(rank, lengths);
                        case InhetoBaseTypes.Char:
                            return BuildArray<char>(rank, lengths);
                        case InhetoBaseTypes.Int16:
                            return BuildArray<short>(rank, lengths);
                        case InhetoBaseTypes.UInt16:
                            return BuildArray<ushort>(rank, lengths);
                        case InhetoBaseTypes.Rune:
                            return BuildArray<Rune>(rank, lengths);
                        case InhetoBaseTypes.Int32:
                            return BuildArray<int>(rank, lengths);
                        case InhetoBaseTypes.UInt32:
                            return BuildArray<uint>(rank, lengths);
                        case InhetoBaseTypes.Int64:
                            return BuildArray<long>(rank, lengths);
                        case InhetoBaseTypes.UInt64:
                            return BuildArray<ulong>(rank, lengths);
                        case InhetoBaseTypes.Half:
                            return BuildArray<Half>(rank, lengths);
                        case InhetoBaseTypes.Single:
                            return BuildArray<float>(rank, lengths);
                        case InhetoBaseTypes.Double:
                            return BuildArray<double>(rank, lengths);
                        case InhetoBaseTypes.Decimal:
                            return BuildArray<decimal>(rank, lengths);
                        case InhetoBaseTypes.String:
                            return BuildArray<string>(rank, lengths);
                        case InhetoBaseTypes.DateOnly:
                            return BuildArray<DateOnly>(rank, lengths);
                        case InhetoBaseTypes.DateTime:
                            return BuildArray<DateTime>(rank, lengths);
                        case InhetoBaseTypes.TimeOnly:
                            return BuildArray<TimeOnly>(rank, lengths);
                        case InhetoBaseTypes.TimeSpan:
                            return BuildArray<TimeSpan>(rank, lengths);
                        case InhetoBaseTypes.Guid:
                            return BuildArray<Guid>(rank, lengths);
                        case InhetoBaseTypes.DateTimeOffset:
                            return BuildArray<DateTimeOffset>(rank, lengths);
                        case InhetoBaseTypes.Version:
                            return BuildArray<Version>(rank, lengths);
                        case InhetoBaseTypes.Uri:
                            return BuildArray<Uri>(rank, lengths);
                        case InhetoBaseTypes.Vector2:
                            return BuildArray<Vector2>(rank, lengths);
                        case InhetoBaseTypes.Vector3:
                            return BuildArray<Vector3>(rank, lengths);
                        case InhetoBaseTypes.Vector4:
                            return BuildArray<Vector4>(rank, lengths);
                        case InhetoBaseTypes.ComplexNumeric:
                            return BuildArray<Complex>(rank, lengths);
                        case InhetoBaseTypes.Quaternion:
                            return BuildArray<Quaternion>(rank, lengths);
                        case InhetoBaseTypes.Plane:
                            return BuildArray<Plane>(rank, lengths);
                        case InhetoBaseTypes.Matrix3x2:
                            return BuildArray<Matrix3x2>(rank, lengths);
                        case InhetoBaseTypes.Matrix4x4:
                            return BuildArray<Matrix4x4>(rank, lengths);
                        case InhetoBaseTypes.BigInteger:
                            return BuildArray<BigInteger>(rank, lengths);
                        case InhetoBaseTypes.ByteArray:
                            return BuildArray<byte[]>(rank, lengths);
                        case InhetoBaseTypes.ListString:
                            return BuildArray<List<string>>(rank, lengths);
                        case InhetoBaseTypes.ComplexType:
                            return BuildArray<object>(rank, lengths);
                        default:
                            throw new NotSupportedException($"Cannot infer a supported multidimensional array element type at '{propPath}'.");
                    }
                case InhetoKindMasks.InhetoNullableBaseType:
                    switch (entry.Type.ArrayInfo.ElementType.NullableBaseType)
                    {
                        case InhetoBaseTypes.Boolean:
                            return BuildArray<bool?>(rank, lengths);
                        case InhetoBaseTypes.SByte:
                            return BuildArray<sbyte?>(rank, lengths);
                        case InhetoBaseTypes.Byte:
                            return BuildArray<byte?>(rank, lengths);
                        case InhetoBaseTypes.Char:
                            return BuildArray<char?>(rank, lengths);
                        case InhetoBaseTypes.Int16:
                            return BuildArray<short?>(rank, lengths);
                        case InhetoBaseTypes.UInt16:
                            return BuildArray<ushort?>(rank, lengths);
                        case InhetoBaseTypes.Rune:
                            return BuildArray<Rune?>(rank, lengths);
                        case InhetoBaseTypes.Int32:
                            return BuildArray<int?>(rank, lengths);
                        case InhetoBaseTypes.UInt32:
                            return BuildArray<uint?>(rank, lengths);
                        case InhetoBaseTypes.Int64:
                            return BuildArray<long?>(rank, lengths);
                        case InhetoBaseTypes.UInt64:
                            return BuildArray<ulong?>(rank, lengths);
                        case InhetoBaseTypes.Half:
                            return BuildArray<Half?>(rank, lengths);
                        case InhetoBaseTypes.Single:
                            return BuildArray<float?>(rank, lengths);
                        case InhetoBaseTypes.Double:
                            return BuildArray<double?>(rank, lengths);
                        case InhetoBaseTypes.Decimal:
                            return BuildArray<decimal?>(rank, lengths);
                        case InhetoBaseTypes.String:
                            return BuildArray<string?>(rank, lengths);
                        case InhetoBaseTypes.DateOnly:
                            return BuildArray<DateOnly?>(rank, lengths);
                        case InhetoBaseTypes.DateTime:
                            return BuildArray<DateTime?>(rank, lengths);
                        case InhetoBaseTypes.TimeOnly:
                            return BuildArray<TimeOnly?>(rank, lengths);
                        case InhetoBaseTypes.TimeSpan:
                            return BuildArray<TimeSpan?>(rank, lengths);
                        case InhetoBaseTypes.Guid:
                            return BuildArray<Guid?>(rank, lengths);
                        case InhetoBaseTypes.DateTimeOffset:
                            return BuildArray<DateTimeOffset?>(rank, lengths);
                        case InhetoBaseTypes.Version:
                            return BuildArray<Version?>(rank, lengths);
                        case InhetoBaseTypes.Uri:
                            return BuildArray<Uri?>(rank, lengths);
                        case InhetoBaseTypes.Vector2:
                            return BuildArray<Vector2?>(rank, lengths);
                        case InhetoBaseTypes.Vector3:
                            return BuildArray<Vector3?>(rank, lengths);
                        case InhetoBaseTypes.Vector4:
                            return BuildArray<Vector4?>(rank, lengths);
                        case InhetoBaseTypes.ComplexNumeric:
                            return BuildArray<Complex?>(rank, lengths);
                        case InhetoBaseTypes.Quaternion:
                            return BuildArray<Quaternion?>(rank, lengths);
                        case InhetoBaseTypes.Plane:
                            return BuildArray<Plane?>(rank, lengths);
                        case InhetoBaseTypes.Matrix3x2:
                            return BuildArray<Matrix3x2?>(rank, lengths);
                        case InhetoBaseTypes.Matrix4x4:
                            return BuildArray<Matrix4x4?>(rank, lengths);
                        case InhetoBaseTypes.BigInteger:
                            return BuildArray<BigInteger?>(rank, lengths);
                        case InhetoBaseTypes.ByteArray:
                            return BuildArray<byte[]?>(rank, lengths);
                        case InhetoBaseTypes.ListString:
                            return BuildArray<List<string>?>(rank, lengths);
                        case InhetoBaseTypes.ComplexType:
                            return BuildArray<object?>(rank, lengths);
                        default:
                            throw new NotSupportedException($"Cannot infer a supported multidimensional array element type at '{propPath}'.");
                    }
                case InhetoKindMasks.InhetoPromotedType:
                    switch (entry.Type.ArrayInfo.ElementType.PromotedType)
                    {
                        case InhetoPromotedTypes.Enum:
                            // Inferred enum shapes retain their stored numeric representation, not source CLR enum identity.
                            switch (entry.Type.ArrayInfo.ElementType.EnumType)
                            {
                                case InhetoBaseTypes.SByte: return BuildArray<sbyte>(rank, lengths);
                                case InhetoBaseTypes.Byte: return BuildArray<byte>(rank, lengths);
                                case InhetoBaseTypes.Int16: return BuildArray<short>(rank, lengths);
                                case InhetoBaseTypes.UInt16: return BuildArray<ushort>(rank, lengths);
                                case InhetoBaseTypes.Int32: return BuildArray<int>(rank, lengths);
                                case InhetoBaseTypes.UInt32: return BuildArray<uint>(rank, lengths);
                                case InhetoBaseTypes.Int64: return BuildArray<long>(rank, lengths);
                                case InhetoBaseTypes.UInt64: return BuildArray<ulong>(rank, lengths);
                            }
                            break;
                        case InhetoPromotedTypes.CultureInfo:
                            return BuildArray<CultureInfo>(rank, lengths);
                        case InhetoPromotedTypes.IPAddress:
                            return BuildArray<IPAddress>(rank, lengths);
                        case InhetoPromotedTypes.IPEndPoint:
                            return BuildArray<IPEndPoint>(rank, lengths);
                        case InhetoPromotedTypes.MailAddress:
                            return BuildArray<MailAddress>(rank, lengths);
                        case InhetoPromotedTypes.MemoryByte:
                            return BuildArray<Memory<byte>>(rank, lengths);
                        case InhetoPromotedTypes.MemoryStream:
                            return BuildArray<MemoryStream>(rank, lengths);
                        case InhetoPromotedTypes.NameValueCollection:
                            return BuildArray<NameValueCollection>(rank, lengths);
                        case InhetoPromotedTypes.StringCollection:
                            return BuildArray<StringCollection>(rank, lengths);
                        case InhetoPromotedTypes.ReadOnlyMemoryByte:
                            return BuildArray<ReadOnlyMemory<byte>>(rank, lengths);
                        case InhetoPromotedTypes.Regex:
                            return BuildArray<Regex>(rank, lengths);
                        case InhetoPromotedTypes.SecureString:
                            return BuildArray<SecureString>(rank, lengths);
                        case InhetoPromotedTypes.StringBuilder:
                            return BuildArray<StringBuilder>(rank, lengths);
                        case InhetoPromotedTypes.TimeZoneInfo:
                            return BuildArray<TimeZoneInfo>(rank, lengths);
                        case InhetoPromotedTypes.Type:
                            return BuildArray<Type>(rank, lengths);
                        case InhetoPromotedTypes.Enumerable:
                            return BuildArray<IEnumerable>(rank, lengths);

                    }
                    break;
            }
            throw new NotSupportedException($"Cannot infer a supported multidimensional array element type at '{propPath}'.");

            string GetArrayToken(int[] indexes)
            {
                sbToken.Clear();
                sbToken.Append('@');
                for (int i = 0; i < rank; i++)
                {
                    sbToken.Append(indexes[i]);
                    if (i + 1 < rank) sbToken.Append(',');
                }
                return sbToken.ToString();
            }

            Array BuildArray<AT>(int rank, int[] lengths)
            {
                var retArray = Array.CreateInstance(typeof(AT), lengths);
                var idxs = new int[rank];

                for (int i = 0; i < retArray.Length; i++)
                {
                    retArray.SetValue(ReadPropInternal($"{propPath}{GetArrayToken(idxs)}", dzOptions), idxs);
                    for (int d = rank - 1; d >= 0; d--)
                    {
                        idxs[d]++;
                        if (idxs[d] < lengths[d]) break;
                        idxs[d] = 0;
                    }
                }


                return retArray;

            }
        }

        internal Array? ReadMDArrayOf<ElementType>(string propPath, DeserializationOptions dzOptions)
        {
            var entry = GetNameEntryFromPropPath(propPath);
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Unknown) return default;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Null) return default;
            bool copy = entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.DuplicateValue;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && (entry.Type.BaseType == InhetoBaseTypes.DuplicateRef || copy))
            {
                entry = NameHeaderEntry.CreateBorrowed(stream, entry.ValueOffset, entry.Name);
            }

            var entryOffset = entry.Index;
            var ret = GetOrAddCached(entryOffset, k =>
            {
                return ReadMDArrayOf<ElementType>(entry, dzOptions);
            });
            return materializationOperationDepth != 0 && copy ? CloneIfMutable(ret) : ret;
        }

        internal Array? ReadMDArrayOf<ElementType>(NameHeaderEntry nvn, DeserializationOptions dzOptions)
        {
            var et = typeof(ElementType);
            if (Nullable.GetUnderlyingType(et) is not null)
                return ReadNullableArray(ArrayTypeFromLeaf(et, nvn), nvn, nvn.PropPath, dzOptions);
            var sbToken = new StringBuilder();
            var propPath = nvn.PropPath;
            var rank = nvn.Type.ArrayInfo.Rank;
            // Preserve existing construction APIs; lengths are prepared only for this requested output, never during header parsing.
            var lengths = new int[rank];
            if (nvn.Type.ArrayInfo.ArrayType != InhetoArrayTypes.ArrayMD || nvn.CopyLengths(lengths) != rank)
                throw new InvalidDataException($"The multidimensional array metadata at '{propPath}' does not contain rank lengths.");

            switch (nvn.Type.ArrayInfo.ElementType.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (nvn.Type.ArrayInfo.ElementType.BaseType)
                    {
                        case InhetoBaseTypes.Boolean:
                            if (et == typeof(bool))
                                return BuildArray<bool>(rank, lengths);
                            else
                                return BuildArray<ElementType>(rank, lengths, true);
                        case InhetoBaseTypes.SByte:
                            if (et == typeof(sbyte))
                                return BuildArray<sbyte>(rank, lengths);
                            else
                                return BuildArray<ElementType>(rank, lengths, true);
                        case InhetoBaseTypes.Byte:
                            if (et == typeof(byte))
                                return BuildArray<byte>(rank, lengths);
                            else
                                return BuildArray<ElementType>(rank, lengths, true);

                        case InhetoBaseTypes.Char:
                            if (et == typeof(char))
                                return BuildArray<char>(rank, lengths);
                            else
                                return BuildArray<ElementType>(rank, lengths, true);
                        case InhetoBaseTypes.Int16:
                            if (et == typeof(short))
                                return BuildArray<short>(rank, lengths);
                            else
                                return BuildArray<ElementType>(rank, lengths, true);
                        case InhetoBaseTypes.UInt16:
                            if (et == typeof(ushort))
                                return BuildArray<ushort>(rank, lengths);
                            else
                                return BuildArray<ElementType>(rank, lengths, true);
                        case InhetoBaseTypes.Rune:
                            if (et == typeof(Rune))
                                return BuildArray<Rune>(rank, lengths);
                            else
                                return BuildArray<ElementType>(rank, lengths, true);
                        case InhetoBaseTypes.Int32:
                            if (et == typeof(int))
                                return BuildArray<int>(rank, lengths);
                            else
