            string GetArrayToken(int[] indexes)
            {
                sbToken.Clear();
                sbToken.Append('@');
                for (int i = 0; i < rank; i++)
                {
                    sbToken.Append(indexes[i]);
                    if (i + 1 < rank) sbToken.Append(',');
                }
                return sbToken.ToString();
            }

            Array BuildArray<AT>(int rank, int[] lengths, bool useCoercion = false)
            {
                var retArray = Array.CreateInstance(typeof(AT), lengths);
                var idxs = new int[rank];

                if (useCoercion)
                {
                    for (int i = 0; i < retArray.Length; i++)
                    {
                        retArray.SetValue(FastCoerce.Coerce<AT>(ReadPropInternal($"{propPath}{GetArrayToken(idxs)}", dzOptions)), idxs);
                        for (int d = rank - 1; d >= 0; d--)
                        {
                            idxs[d]++;
                            if (idxs[d] < lengths[d]) break;
                            idxs[d] = 0;
                        }
                    }
                }
                else
                {
                    for (int i = 0; i < retArray.Length; i++)
                    {
                        retArray.SetValue(ReadPropInternal($"{propPath}{GetArrayToken(idxs)}", dzOptions), idxs);
                        for (int d = rank - 1; d >= 0; d--)
                        {
                            idxs[d]++;
                            if (idxs[d] < lengths[d]) break;
                            idxs[d] = 0;
                        }
                    }
                }


                return retArray;

            }
        }

        private object? ReadDictionaryValue(Type valueType, string propPath, DeserializationOptions dzOptions)
        {
            if (valueType == typeof(object))
                return ReadPropInternal(propPath, dzOptions);

            var isSimple = valueType.IsEnum
                || InhetoBaseTypesMap.ContainsKey(valueType.TypeHandle)
                || InhetoPromotedTypesMap.ContainsKey(valueType.TypeHandle);

            if (isSimple || ((valueType.IsInterface || valueType.IsAbstract) && !dzOptions.HasActivator(valueType)))
            {
                var value = ReadPropInternal(propPath, dzOptions);
                if (FastCoerce.TryCoerce(value, valueType, out var converted)) return converted;
                throw new InvalidCastException($"Core cannot convert the value at '{propPath}' from '{value?.GetType().FullName ?? "null"}' to '{valueType.FullName}'.");
            }

            return ReadMaterializedAs(valueType, propPath, dzOptions);
        }

        #region ReadMaterializedAs
        internal T? ReadPropAs<T>(NameHeaderEntry entry, DeserializationOptions? dzOptions = null, bool throwOnTypeMismatch = true)
        {
            dzOptions ??= deserializationOptions;
            return ReadMaterializedAs<T>(default, entry, entry.PropPath, dzOptions, throwOnTypeMismatch);
        }

        private T? ReadMaterializedAs<T>(T? instance, string propPath, DeserializationOptions? dzOptions = null, bool throwOnTypeMismatch = true)
        {
            dzOptions ??= deserializationOptions;
            var entry = GetNameEntryFromPropPath(propPath, dzOptions, out string resolvedPath);
            if (instance is null &&
                propPath.Length == 0 &&
                entry.Kind == InhetoKindMasks.InhetoBaseType &&
                entry.Type.BaseType == InhetoBaseTypes.ComplexType)
            {
                return MaterializeComplexRoot<T>(resolvedPath, dzOptions);
            }

            return ReadMaterializedAs<T>(instance, entry, resolvedPath, dzOptions, throwOnTypeMismatch, propPath);
        }

        private T? ReadMaterializedAs<T>(T? instance, NameHeaderEntry entry, string propPath, DeserializationOptions? dzOptions = null, bool throwOnTypeMismatch = true, string? requestedPath = null)
        {
            dzOptions ??= deserializationOptions;
            var originalBaseType = entry.Type.BaseType;
            if (!entry.IsEmpty)
            {
                if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Unknown) return default;
                if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Null) return default;
                if (entry.Kind == InhetoKindMasks.InhetoBaseType &&
                    entry.Type.BaseType is InhetoBaseTypes.DuplicateRef or InhetoBaseTypes.DuplicateValue)
                {
                    entry = NameHeaderEntry.CreateBorrowed(stream, entry.ValueOffset, entry.Name);
                    if (entry.Index == 1 && activeComplexRoot is T root)
                        return root;
                }
            }
            else if (entry.IsEmpty)
            {
                var partial = GetClosestAliasedNameEntry(requestedPath ?? propPath, dzOptions);
                // If we didn’t make progress, don’t recurse back into the same node
                if (partial.Entry is null || string.IsNullOrEmpty(partial.RemainingPath))
                    return default;

                var partialObject = ReadPropInternal(partial.Entry.Value.PropPath, dzOptions);
                if (partialObject == null) return default;
                return ValuePathRetriever.GetValue<T>(partialObject, partial.RemainingPath)!;
            }

            if (entry.Kind == InhetoKindMasks.InhetoBaseType &&
                entry.Type.BaseType is InhetoBaseTypes.CustomProp or InhetoBaseTypes.CustomType &&
                originalBaseType != InhetoBaseTypes.DuplicateValue)
            {
                if (TryReadCustomValue(entry, requestedPath ?? propPath, propPath, originalBaseType == InhetoBaseTypes.DuplicateRef, null, dzOptions, out var customValue))
                    return FastCoerce.Coerce<T>(customValue);
                return (T?)ReadCustomFallback(entry, typeof(T), requestedPath ?? propPath);
            }

            if (typeof(T).IsArray && IsComplexArrayShape(typeof(T), entry, dzOptions.MemberTypes))
                return (T)(object)ReadComplexArray(typeof(T), entry, propPath, dzOptions, instance as Array);

            if (materializationOperationDepth != 0 && instance is List<string> suppliedStrings &&
                entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.ListString)
                return (T)(object)ReadOperationStringList(entry, propPath, suppliedStrings);

            if (materializationOperationDepth != 0 && entry.Kind == InhetoKindMasks.InhetoPromotedType)
            {
                if (entry.Type.PromotedType == InhetoPromotedTypes.NameValueCollection && instance is NameValueCollection suppliedNames)
                    return (T)(object)ReadOperationNameValues(entry, suppliedNames);
                if (entry.Type.PromotedType == InhetoPromotedTypes.StringCollection && instance is StringCollection suppliedCollection)
                    return (T)(object)ReadOperationStrings(entry, propPath, suppliedCollection);
            }

            if (materializationOperationDepth != 0 && typeof(T) == typeof(MemoryStream) &&
                (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.ByteArray ||
                 entry.Kind == InhetoKindMasks.InhetoPromotedType && entry.Type.PromotedType is
                    InhetoPromotedTypes.MemoryByte or InhetoPromotedTypes.ReadOnlyMemoryByte or InhetoPromotedTypes.MemoryStream))
                return (T)(object)ReadOperationMemoryStream(entry, propPath, writable: false, copy: originalBaseType == InhetoBaseTypes.DuplicateValue);

            var entryOffset = entry.Index;
            if (entry.Kind == InhetoKindMasks.InhetoPromotedType && entry.Type.PromotedType == InhetoPromotedTypes.Enumerable &&
                TryGetEnumerableCollectionElementType(typeof(T), out var enumerableElementType))
            {
                var enumerableValue = ReadEnumerableCollection(typeof(T), enumerableElementType, instance, entry,
                    propPath, requestedPath ?? propPath, dzOptions);
                return (T?)(materializationOperationDepth != 0 && originalBaseType == InhetoBaseTypes.DuplicateValue && enumerableValue is List<string>
                    ? CloneIfMutable(enumerableValue) : enumerableValue);
            }
            bool collectionPublication = materializationOperationDepth != 0 && entry.Kind == InhetoKindMasks.InhetoCollectionType;
            if (materializationOperationDepth != 0 &&
                (collectionPublication || entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.ComplexType))
            {
                if (!collectionPublication && originalBaseType == InhetoBaseTypes.DuplicateRef &&
                    (refCache is null || !refCache.ContainsKey(entryOffset)))
                    TryHydrateCanonicalMember(entryOffset, dzOptions);
                if (refCache is not null && refCache.TryGetValue(entryOffset, out var canonical) &&
                    (canonical is null || !typeof(T).IsInstanceOfType(canonical) ||
                     collectionPublication && instance is not null && !ReferenceEquals(instance, canonical)))
                {
                    // A declined canonical element remains null for later missing slots, rather than retrying its activator.
                    // A supplied slot can still fill independently, restoring the intentional null publication afterwards.
                    if (canonical is null && instance is null) return default;
                    // Incompatible destination shapes are independent projections, not failed source-reference assignments.
                    // Temporarily publish the requested projection for its own cycles, then restore the canonical instance.
                    try { return (T?)factory(entryOffset); }
                    finally { RefCache[entryOffset] = canonical!; }
                }
            }
            object? ret;
            try { ret = GetOrAddCached(entryOffset, k => factory(k), preserveIdentity: collectionPublication); }
            catch
            {
                // An unsuccessful collection fill must not leave a partly rebuilt referent in this operation.
                if (collectionPublication) RefCache.Remove(entryOffset);
                throw;
            }

            if (materializationOperationDepth != 0 && originalBaseType == InhetoBaseTypes.DuplicateValue && ret is Array or List<string> or NameValueCollection or StringCollection or MemoryStream or StringBuilder)
                ret = CloneIfMutable(ret);
            return ret is null ? default : (T?)ret;
            object? factory(uint key_)
            {

                var tType = typeof(T);
                var nvn = entry;
                var nvnIndex = nvn.Index;
                if (nvn.Kind == InhetoKindMasks.InhetoBaseType && nvn.Type.BaseType == InhetoBaseTypes.Unknown)
                    return default;

                T? ret = default;
                var useCoercion = true;

                switch (nvn.Kind)
                {
                    case InhetoKindMasks.InhetoBaseType:
