                                    {
                                        case InhetoBaseTypes.ComplexType:
                                            {
                                                // A derived collection can have complex shape metadata while its cached mutator knows the declared element type.
                                                // Arrays are constructed from their encoded shape, not a parameterless constructor.
                                                if (collectionElementType is { IsArray: true } arrayElementType)
                                                {
                                                    for (int i = mutator.ReverseEncodedOrder ? checked((int)dCount) - 1 : 0,
                                                        slotEnd = mutator.ReverseEncodedOrder ? -1 : checked((int)dCount), slotStep = mutator.ReverseEncodedOrder ? -1 : 1;
                                                        i != slotEnd; i += slotStep)
                                                    {
                                                        var elementPath = $"{propPath}#{i}";
                                                        if (GetNameEntryFromPropPath(elementPath).IsEmpty) continue;
                                                        mutator.Add(instance, ReadMaterializedAs(arrayElementType, elementPath, dzOptions));
                                                    }
                                                    break;
                                                }
                                                FillCollectionElements(collectionElementType, instance, dCount, propPath, dzOptions);
                                                break;

                                            }
                                        case InhetoBaseTypes.Boolean:
                                            FillBooleanList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Char:
                                            FillCharList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Rune:
                                            FillRuneList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.String:
                                            FillStringList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.SByte:
                                            FillSByteList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Byte:
                                            FillByteList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Int16:
                                            FillInt16List(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.UInt16:
                                            FillUInt16List(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Int32:
                                            FillInt32List(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.UInt32:
                                            FillUInt32List(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Int64:
                                            FillInt64List(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.UInt64:
                                            FillUInt64List(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Int128:
                                            FillInt128List(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.UInt128:
                                            FillUInt128List(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Half:
                                            FillHalfList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Single:
                                            FillSingleList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Double:
                                            FillDoubleList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Decimal:
                                            FillDecimalList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.DateOnly:
                                            FillDateOnlyList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.DateTime:
                                            FillDateTimeList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.DateTimeOffset:
                                            FillDateTimeOffsetList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.TimeOnly:
                                            FillTimeOnlyList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.TimeSpan:
                                            FillTimeSpanList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Guid:
                                            FillGuidList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Version:
                                            FillVersionList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Uri:
                                            FillUriList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Vector2:
                                            FillVector2List(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Vector3:
                                            FillVector3List(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Vector4:
                                            FillVector4List(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.ComplexNumeric:
                                            FillComplexNumericList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Quaternion:
                                            FillQuaternionList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Plane:
                                            FillPlaneList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Matrix3x2:
                                            FillMatrix3x2List(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.Matrix4x4:
                                            FillMatrix4x4List(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.BigInteger:
                                            FillBigIntegerList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.ByteArray:
                                            FillByteArrayList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoBaseTypes.ListString:
                                            FillListStringList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;

                                    }
                                    break;
                                case InhetoKindRoute.Promoted:
                                    switch (elementTypeInfo.PromotedType)
                                    {
                                        case InhetoPromotedTypes.Enum:
                                            switch (elementTypeInfo.BaseType)
                                            {
                                                case InhetoBaseTypes.SByte:
                                                    FillEnumList<sbyte>(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                                    break;
                                                case InhetoBaseTypes.Byte:
                                                    FillEnumList<byte>(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                                    break;
                                                case InhetoBaseTypes.Int16:
                                                    FillEnumList<short>(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                                    break;
                                                case InhetoBaseTypes.UInt16:
                                                    FillEnumList<ushort>(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                                    break;
                                                case InhetoBaseTypes.Int32:
                                                    FillEnumList<int>(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                                    break;
                                                case InhetoBaseTypes.UInt32:
                                                    FillEnumList<uint>(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                                    break;
                                                case InhetoBaseTypes.Int64:
                                                    FillEnumList<long>(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                                    break;
                                                case InhetoBaseTypes.UInt64:
                                                    FillEnumList<ulong>(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                                    break;
                                            }
                                            break;
                                        case InhetoPromotedTypes.CultureInfo:
                                            FillCultureInfoList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoPromotedTypes.IPAddress:
                                            // need to handle ReadOnlyIPAddress
                                            FillIPAddressList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoPromotedTypes.IPEndPoint:
                                            FillIPEndPointList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoPromotedTypes.MailAddress:
                                            FillMailAddressList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoPromotedTypes.MemoryByte:
                                            FillMemoryByteList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoPromotedTypes.MemoryStream:
                                            FillMemoryStreamList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoPromotedTypes.ReadOnlyMemoryByte:
                                            FillReadOnlyMemoryByteList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoPromotedTypes.StringBuilder:
                                            FillStringBuilderList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoPromotedTypes.TimeZoneInfo:
                                            FillTimeZoneInfoList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoPromotedTypes.Regex:
                                            FillRegexList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoPromotedTypes.SecureString:
                                            FillSecureStringList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoPromotedTypes.Type:
                                            FillTypeList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoPromotedTypes.NameValueCollection:
                                            FillNameValueCollectionList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                        case InhetoPromotedTypes.StringCollection:
                                            FillStringCollectionList(nvn, instance as IEnumerable, useCoercion, throwOnTypeMismatch);
                                            break;
                                    }
                                    break;

                            }
                        }
                        ret = instance;
                        return ret;
                    default:
                        break;
                }
                return default;

            }
            ;
        }
