        void SetPropFieldBigInteger(object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (nvn.Type.BaseType)
                    {
                        case InhetoBaseTypes.BigInteger:
                            acc.SetValue(ref obj, ReadBigIntegerCore(propPath));
                            break;
                    }
                    break;
            }
        }

        private void SetPropFieldBoolean(object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry entry, IAccessors acc)
        {
            switch (entry.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (entry.Type.BaseType)
                    {
                        case InhetoBaseTypes.Boolean:
                            acc.SetValue(ref obj, ReadBooleanCore(propPath) ?? default);
                            break;
                        case InhetoBaseTypes.SByte:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, ReadSByteCore(propPath).GetValueOrDefault() > 0);
                            break;
                        case InhetoBaseTypes.Byte:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, ReadByteCore(propPath).GetValueOrDefault() > 0);
                            break;
                        case InhetoBaseTypes.Int16:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, ReadInt16Core(propPath).GetValueOrDefault() > 0);
                            break;
                        case InhetoBaseTypes.UInt16:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, ReadUInt16Core(propPath).GetValueOrDefault() > 0);
                            break;
                        case InhetoBaseTypes.Int32:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, ReadInt32Core(propPath).GetValueOrDefault() > 0);
                            break;
                        case InhetoBaseTypes.UInt32:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, ReadUInt32Core(propPath).GetValueOrDefault() > 0);
                            break;
                        case InhetoBaseTypes.Int64:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, ReadInt64Core(propPath).GetValueOrDefault() > 0);
                            break;
                        case InhetoBaseTypes.UInt64:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, ReadUInt64Core(propPath).GetValueOrDefault() > 0);
                            break;
                        default:
                            if (throwOnTypeMismatch) throw new InvalidCastException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                            break;

                    }
                    break;
            }
        }

        private void SetPropFieldByte(object obj, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry entry, IAccessors acc)
        {
            switch (entry.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (entry.Type.BaseType)
                    {
                        case InhetoBaseTypes.Byte:
                            acc.SetValue(ref obj, ReadByteCore(propPath) ?? default);
                            break;

                        case InhetoBaseTypes.SByte:
                            var b2sb = ReadSByteCore(propPath) ?? default;
                            if (b2sb < byte.MinValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (byte)b2sb);
                            break;

                        case InhetoBaseTypes.Int16:
                            var b2sh = ReadInt16Core(propPath) ?? default;
                            if (b2sh > byte.MaxValue || b2sh < byte.MinValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (byte)b2sh);
                            break;

                        case InhetoBaseTypes.UInt16:
                            var b2ush = ReadUInt16Core(propPath) ?? default;
                            if (b2ush > byte.MaxValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (byte)b2ush);
                            break;

                        case InhetoBaseTypes.Int32:
                            var b2i = ReadInt32Core(propPath) ?? default;
                            if (b2i > byte.MaxValue || b2i < byte.MinValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (byte)b2i);
                            break;

                        case InhetoBaseTypes.UInt32:
                            var b2ui = ReadUInt32Core(propPath) ?? default;
                            if (b2ui > byte.MaxValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (byte)b2ui);
                            break;

                        case InhetoBaseTypes.Int64:
                            var b2l = ReadInt64Core(propPath) ?? default;
                            if (b2l > byte.MaxValue || b2l < byte.MinValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (byte)b2l);
                            break;

                        case InhetoBaseTypes.UInt64:
                            var b2ul = ReadUInt64Core(propPath) ?? default;
                            if (b2ul > byte.MaxValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (byte)b2ul);
                            break;
                    }
                    break;
            }
        }

        void SetPropFieldByteArray(object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
