                    }
                    break;
            }
        }

        private void SetPropFieldChar(object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry entry, IAccessors acc)
        {
            switch (entry.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (entry.Type.BaseType)
                    {
                        case InhetoBaseTypes.Char:
                            acc.SetValue(ref obj, ReadCharCore(propPath) ?? default);
                            break;
                        case InhetoBaseTypes.String:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, ReadStringCore(propPath)?[0] ?? default);
                            break;
                        case InhetoBaseTypes.Rune:
                            if (!useCoercion) break;
                            var runeInt = (ReadRuneCore(propPath) ?? default).Value;
                            if (runeInt > char.MaxValue)
                                if (throwOnTypeMismatch) throw new InvalidCastException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else
                                    break;

                            acc.SetValue(ref obj, (char)runeInt);
                            break;
                        case InhetoBaseTypes.SByte:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (char)ReadSByteCore(propPath).GetValueOrDefault());
                            break;
                        case InhetoBaseTypes.Byte:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (char)ReadByteCore(propPath).GetValueOrDefault());
                            break;
                        case InhetoBaseTypes.Int16:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (char)ReadInt16Core(propPath).GetValueOrDefault());
                            break;
                        case InhetoBaseTypes.UInt16:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (char)ReadUInt16Core(propPath).GetValueOrDefault());
                            break;
                        case InhetoBaseTypes.Int32:
                            if (!useCoercion) break;
                            var ci = ReadInt32Core(propPath).GetValueOrDefault();
                            if (ci > char.MaxValue)
                                if (throwOnTypeMismatch) throw new InvalidCastException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else
                                    break;
                            acc.SetValue(ref obj, (char)ci);
                            break;
                        case InhetoBaseTypes.UInt32:
                            if (!useCoercion) break;
                            var cui = ReadUInt32Core(propPath).GetValueOrDefault();
                            if (cui > char.MaxValue)
                                if (throwOnTypeMismatch) throw new InvalidCastException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else
                                    break;
                            acc.SetValue(ref obj, (char)cui);
                            break;
                        default:
                            if (throwOnTypeMismatch) throw new InvalidCastException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                            break;
                    }
                    break;
            }
        }

        private void SetPropFieldComplex(object obj, string propPath, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (nvn.Type.BaseType)
                    {
                        case InhetoBaseTypes.ComplexNumeric:
                            var vcn = ReadComplexCore(propPath);
                            if (vcn is not null) acc.SetValue(ref obj, vcn);
                            break;
                    }
                    break;
            }
        }

        void SetPropFieldCultureInfo(ref object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoPromotedType:
                    switch (nvn.Type.PromotedType)
                    {
                        case InhetoPromotedTypes.CultureInfo:
                            acc.SetValue(ref obj, new CultureInfo(ReadStringCore(propPath) ?? throw new InvalidDataException($"Missing CultureInfo payload at '{propPath}'.")));
                            break;
                    }
                    break;
                case InhetoKindMasks.InhetoBaseType:
                    switch (nvn.Type.BaseType)
                    {
                        case InhetoBaseTypes.String:
                            if (!useCoercion) break;
                            try
                            {
                                acc.SetValue(ref obj, new CultureInfo(ReadStringCore(propPath) ?? throw new InvalidDataException($"Missing CultureInfo conversion text at '{propPath}'.")));
                            }
                            catch (Exception ex)
                            {
                                if (throwOnTypeMismatch) throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}", ex);
                            }
                            break;
                    }
                    break;
            }
        }

        private void SetPropFieldDateOnly(object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (nvn.Type.BaseType)
                    {
                        case InhetoBaseTypes.DateOnly:
                            acc.SetValue(ref obj, ReadDateOnlyCore(propPath) ?? default);
                            break;
                        case InhetoBaseTypes.DateTime:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, DateOnly.FromDateTime(ReadDateTimeCore(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.DateTimeOffset:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, DateOnly.FromDateTime((ReadDateTimeOffsetCore(propPath) ?? default).DateTime));
                            break;
                        case InhetoBaseTypes.String:
                            if (!useCoercion) break;
                            try
                            {
                                acc.SetValue(ref obj, DateOnly.Parse(ReadStringCore(propPath) ?? throw new InvalidDataException($"Missing DateOnly conversion text at '{propPath}'.")));
                            }
                            catch (Exception ex)
                            {
                                if (throwOnTypeMismatch) throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}", ex);
                            }
                            break;
                    }
                    break;

            }
        }

        private void SetPropFieldDateTime(object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (nvn.Type.BaseType)
                    {
                        case InhetoBaseTypes.DateTime:
                            acc.SetValue(ref obj, ReadDateTimeCore(propPath) ?? default);
                            break;
                        case InhetoBaseTypes.DateOnly:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (ReadDateOnlyCore(propPath) ?? default).ToDateTime(TimeOnly.MinValue));
                            break;
                        case InhetoBaseTypes.DateTimeOffset:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (ReadDateTimeOffsetCore(propPath) ?? default).DateTime);
                            break;
                        case InhetoBaseTypes.String:
                            if (!useCoercion) break;
                            try
                            {
                                acc.SetValue(ref obj, DateTime.Parse(ReadStringCore(propPath) ?? throw new InvalidDataException($"Missing DateTime conversion text at '{propPath}'.")));
                            }
                            catch (Exception ex)
                            {
                                if (throwOnTypeMismatch) throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}", ex);
                            }
                            break;
                    }
                    break;
            }
        }

        private void SetPropFieldDateTimeOffset(object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (nvn.Type.BaseType)
                    {
                        case InhetoBaseTypes.DateTimeOffset:
                            acc.SetValue(ref obj, ReadDateTimeOffsetCore(propPath) ?? default);
                            break;
                        case InhetoBaseTypes.DateOnly:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, new DateTimeOffset((ReadDateOnlyCore(propPath) ?? default).ToDateTime(TimeOnly.MinValue)));
                            break;
                        case InhetoBaseTypes.DateTime:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, new DateTimeOffset((ReadDateTimeCore(propPath) ?? default)));
                            break;
                        case InhetoBaseTypes.String:
                            if (!useCoercion) break;
                            try
                            {
                                acc.SetValue(ref obj, DateTimeOffset.Parse(ReadStringCore(propPath) ?? throw new InvalidDataException($"Missing DateTimeOffset conversion text at '{propPath}'.")));
                            }
                            catch (Exception ex)
                            {
                                if (throwOnTypeMismatch) throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}", ex);
                            }
                            break;
                    }
                    break;
            }
        }

        private void SetPropFieldDecimal(object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (nvn.Type.BaseType)
                    {
                        case InhetoBaseTypes.Decimal:
                            acc.SetValue(ref obj, ReadDecimalCore(propPath) ?? default);
                            break;

                        // integral → always fits
                        case InhetoBaseTypes.SByte:
                            acc.SetValue(ref obj, (decimal)(ReadSByteCore(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Byte:
                            acc.SetValue(ref obj, (decimal)(ReadByteCore(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Int16:
                            acc.SetValue(ref obj, (decimal)(ReadInt16Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.UInt16:
                            acc.SetValue(ref obj, (decimal)(ReadUInt16Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Int32:
                            acc.SetValue(ref obj, (decimal)(ReadInt32Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.UInt32:
                            acc.SetValue(ref obj, (decimal)(ReadUInt32Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Int64:
                            acc.SetValue(ref obj, (decimal)(ReadInt64Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.UInt64:
                            acc.SetValue(ref obj, (decimal)(ReadUInt64Core(propPath) ?? default));
                            break;

                        // floating-point → lossy, gated by useCoercion
                        case InhetoBaseTypes.Half:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (decimal)(ReadHalfCore(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Single:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (decimal)(ReadSingleCore(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Double:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (decimal)(ReadDoubleCore(propPath) ?? default));
                            break;

                        default:
                            if (throwOnTypeMismatch)
                                throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                            break;
                    }
                    break;
            }
        }

