        void SetPropFieldEnum(ref object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            if (nvn.Kind == InhetoKindMasks.InhetoPromotedType &&
                nvn.Type.PromotedType == InhetoPromotedTypes.Enum &&
                nvn.Type.EnumType == projectedTypeInfo.BaseType)
            {
                var enumType = Nullable.GetUnderlyingType(acc.MemberType) ?? acc.MemberType;
                acc.SetValue(ref obj, ReadResolvedEnumValue(nvn, enumType));
                return;
            }

            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoPromotedType:
                    switch (nvn.Type.PromotedType)
                    {
                        case InhetoPromotedTypes.Enum:
                            switch (projectedTypeInfo.BaseType)
                            {
                                case InhetoBaseTypes.SByte:
                                    if (nvn.Type.EnumType == InhetoBaseTypes.SByte)
                                        acc.SetValue(ref obj, ReadSByteCore(propPath));
                                    else
                                        SetValue<sbyte>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                                    break;
                                case InhetoBaseTypes.Byte:
                                    if (nvn.Type.EnumType == InhetoBaseTypes.Byte)
                                        acc.SetValue(ref obj, ReadByteCore(propPath));
                                    else
                                        SetValue<byte>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                                    break;
                                case InhetoBaseTypes.Int16:
                                    if (nvn.Type.EnumType == InhetoBaseTypes.Int16)
                                        acc.SetValue(ref obj, ReadInt16Core(propPath));
                                    else
                                        SetValue<Int16>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                                    break;
                                case InhetoBaseTypes.UInt16:
                                    if (nvn.Type.EnumType == InhetoBaseTypes.UInt16)
                                        acc.SetValue(ref obj, ReadUInt16Core(propPath));
                                    else
                                        SetValue<UInt16>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                                    break;
                                case InhetoBaseTypes.Int32:
                                    if (nvn.Type.EnumType == InhetoBaseTypes.Int32)
                                        acc.SetValue(ref obj, ReadInt32Core(propPath));
                                    else
                                        SetValue<Int32>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                                    break;
                                case InhetoBaseTypes.UInt32:
                                    if (nvn.Type.EnumType == InhetoBaseTypes.UInt32)
                                        acc.SetValue(ref obj, ReadUInt32Core(propPath));
                                    else
                                        SetValue<UInt32>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                                    break;
                                case InhetoBaseTypes.Int64:
                                    if (nvn.Type.EnumType == InhetoBaseTypes.Int64)
                                        acc.SetValue(ref obj, ReadInt64Core(propPath));
                                    else
                                        SetValue<Int64>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                                    break;
                                case InhetoBaseTypes.UInt64:
                                    if (nvn.Type.EnumType == InhetoBaseTypes.UInt64)
                                        acc.SetValue(ref obj, ReadUInt64Core(propPath));
                                    else
                                        SetValue<UInt64>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                                    break;
                                case InhetoBaseTypes.Int128:
                                    if (nvn.Type.EnumType == InhetoBaseTypes.Int128)
                                        acc.SetValue(ref obj, ReadInt128Core(propPath));
                                    else
                                        SetValue<Int128>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                                    break;
                                case InhetoBaseTypes.UInt128:
                                    if (nvn.Type.EnumType == InhetoBaseTypes.UInt128)
                                        acc.SetValue(ref obj, ReadUInt128Core(propPath));
                                    else
                                        SetValue<UInt128>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                                    break;
                            }
                            break;
                    }
                    break;
                case InhetoKindMasks.InhetoBaseType:
                    switch (projectedTypeInfo.BaseType)
                    {
                        case InhetoBaseTypes.SByte:
                            if (nvn.Type.BaseType == InhetoBaseTypes.SByte)
                                acc.SetValue(ref obj, ReadSByteCore(propPath));
                            else
                                SetValue<sbyte>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                            break;
                        case InhetoBaseTypes.Byte:
                            if (nvn.Type.BaseType == InhetoBaseTypes.Byte)
                                acc.SetValue(ref obj, ReadByteCore(propPath));
                            else
                                SetValue<byte>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                            break;
                        case InhetoBaseTypes.Int16:
                            if (nvn.Type.BaseType == InhetoBaseTypes.Int16)
                                acc.SetValue(ref obj, ReadInt16Core(propPath));
                            else
                                SetValue<Int16>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                            break;
                        case InhetoBaseTypes.UInt16:
                            if (nvn.Type.BaseType == InhetoBaseTypes.UInt16)
                                acc.SetValue(ref obj, ReadUInt16Core(propPath));
                            else
                                SetValue<UInt16>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                            break;
                        case InhetoBaseTypes.Int32:
                            if (nvn.Type.BaseType == InhetoBaseTypes.Int32)
                                acc.SetValue(ref obj, ReadInt32Core(propPath));
                            else
                                SetValue<Int32>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                            break;
                        case InhetoBaseTypes.UInt32:
                            if (nvn.Type.BaseType == InhetoBaseTypes.UInt32)
                                acc.SetValue(ref obj, ReadUInt32Core(propPath));
                            else
                                SetValue<UInt32>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                            break;
                        case InhetoBaseTypes.Int64:
                            if (nvn.Type.BaseType == InhetoBaseTypes.Int64)
                                acc.SetValue(ref obj, ReadInt64Core(propPath));
                            else
                                SetValue<Int64>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                            break;
                        case InhetoBaseTypes.UInt64:
                            if (nvn.Type.BaseType == InhetoBaseTypes.UInt64)
                                acc.SetValue(ref obj, ReadUInt64Core(propPath));
                            else
                                SetValue<UInt64>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                            break;
                        case InhetoBaseTypes.Int128:
                            if (nvn.Type.BaseType == InhetoBaseTypes.Int128)
                                acc.SetValue(ref obj, ReadInt128Core(propPath));
                            else
                                SetValue<Int128>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                            break;
                        case InhetoBaseTypes.UInt128:
                            if (nvn.Type.BaseType == InhetoBaseTypes.UInt128)
                                acc.SetValue(ref obj, ReadUInt128Core(propPath));
                            else
                                SetValue<UInt128>(obj, useCoercion, propPath, projectedTypeInfo, nvn, acc);
                            break;
                    }
                    break;
            }

            void SetValue<VType>(object obj, bool useCoercion, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
            {
                switch (nvn.Type.BaseType)
                {
                    case InhetoBaseTypes.SByte:
                        if (useCoercion)
                            acc.SetValue(ref obj, FastCoerce.Coerce<VType>(ReadByteCore(propPath)));
                        else
                            throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                        break;
                    case InhetoBaseTypes.Byte:
                        if (useCoercion)
                            acc.SetValue(ref obj, FastCoerce.Coerce<VType>(ReadByteCore(propPath)));
                        else
                            throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                        break;
                    case InhetoBaseTypes.Int16:
                        if (useCoercion)
                            acc.SetValue(ref obj, FastCoerce.Coerce<VType>(ReadInt16Core(propPath)));
                        else
                            throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                        break;
                    case InhetoBaseTypes.UInt16:
                        if (useCoercion)
                            acc.SetValue(ref obj, FastCoerce.Coerce<VType>(ReadUInt16Core(propPath)));
                        else
                            throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                        break;
                    case InhetoBaseTypes.Int32:
                        if (useCoercion)
                            acc.SetValue(ref obj, FastCoerce.Coerce<VType>(ReadInt32Core(propPath)));
                        else
                            throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                        break;
                    case InhetoBaseTypes.UInt32:
                        if (useCoercion)
                            acc.SetValue(ref obj, FastCoerce.Coerce<VType>(ReadUInt32Core(propPath)));
                        else
                            throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                        break;
                    case InhetoBaseTypes.Int64:
                        if (useCoercion)
                            acc.SetValue(ref obj, FastCoerce.Coerce<VType>(ReadInt64Core(propPath)));
                        else
                            throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                        break;
                    case InhetoBaseTypes.UInt64:
                        if (useCoercion)
                            acc.SetValue(ref obj, FastCoerce.Coerce<VType>(ReadUInt64Core(propPath)));
                        else
                            throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                        break;
                    case InhetoBaseTypes.Int128:
                        if (useCoercion)
                            acc.SetValue(ref obj, FastCoerce.Coerce<VType>(ReadInt128Core(propPath)));
                        else
                            throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                        break;
                    case InhetoBaseTypes.UInt128:
                        if (useCoercion)
                            acc.SetValue(ref obj, FastCoerce.Coerce<VType>(ReadUInt128Core(propPath)));
                        else
                            throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                        break;

                }
            }
        }

        /// <summary>
        /// Reads one enum from the already-resolved name-header entry and returns the correctly typed enum value.<br/>
        /// Consuming the supplied entry is required when the original property header is a duplicate-value marker; looking the property path up again would read the marker offset as the enum payload.<br/>
        /// The stream position is restored so callers retain the same cursor behavior as the public typed readers.<br/>
        /// </summary>
        /// <param name="entry">Resolved enum entry whose value offset points at the underlying numeric payload.<br/></param>
        /// <param name="enumType">Concrete non-nullable enum type to construct.<br/></param>
        /// <returns>The enum value represented by the stored underlying numeric payload.<br/></returns>
        private object ReadResolvedEnumValue(NameHeaderEntry entry, Type enumType)
        {
            var originalPosition = stream.Position;
            try
            {
                object underlyingValue;
                switch (entry.Type.EnumType)
                {
                    case InhetoBaseTypes.SByte:
                        underlyingValue = unchecked((sbyte)entry.ValueOffset);
                        break;
                    case InhetoBaseTypes.Byte:
                        underlyingValue = unchecked((byte)entry.ValueOffset);
                        break;
                    case InhetoBaseTypes.Int16:
                        underlyingValue = unchecked((short)entry.ValueOffset);
                        break;
                    case InhetoBaseTypes.UInt16:
                        underlyingValue = unchecked((ushort)entry.ValueOffset);
                        break;
                    case InhetoBaseTypes.Int32:
                        underlyingValue = unchecked((int)entry.ValueOffset);
                        break;
                    case InhetoBaseTypes.UInt32:
                        underlyingValue = entry.ValueOffset;
                        break;
                    case InhetoBaseTypes.Int64:
                        stream.Position = entry.ValueOffset;
                        underlyingValue = stream.ReadInt64();
                        break;
                    case InhetoBaseTypes.UInt64:
                        stream.Position = entry.ValueOffset;
                        underlyingValue = stream.ReadUInt64();
                        break;
                    default:
                        throw new InvalidDataException($"Unsupported enum underlying type '{entry.Type.EnumType}'.");
                }
                return Enum.ToObject(enumType, underlyingValue);
            }
            finally
            {
                stream.Position = originalPosition;
            }
        }

        void SetPropFieldEnumerable(ref object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc, DeserializationOptions? dzOptions)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoPromotedType:
                    switch (nvn.Type.PromotedType)
                    {
                        case InhetoPromotedTypes.Enumerable:
                            var enu = acc.GetValue(obj);
                            if (enu is null)
                                acc.SetValue(ref obj, ReadMaterializedEnumerable(propPath, dzOptions: dzOptions));
                            else
                                ReadMaterializedEnumerable(propPath, enu as IEnumerable, dzOptions);
                            break;
                    }
                    break;
                case InhetoKindMasks.InhetoCollectionType:
                    if (useCoercion)
                        switch (nvn.Type.CollectionInfo.CollectionType)
                        {
                            case InhetoCollectionTypes.List:
                            case InhetoCollectionTypes.Queue:
                            case InhetoCollectionTypes.ConcurrentQueue:
                            case InhetoCollectionTypes.Stack:
                            case InhetoCollectionTypes.ConcurrentStack:
                            case InhetoCollectionTypes.ObservableCollection:
                            case InhetoCollectionTypes.ConcurrentBag:
                            case InhetoCollectionTypes.SortedSet:
                            case InhetoCollectionTypes.HashSet:
                                var enu = acc.GetValue(obj);
                                if (enu is null)
                                    acc.SetValue(ref obj, ReadMaterializedEnumerable(propPath, dzOptions: dzOptions));
                                else
                                    ReadMaterializedEnumerable(propPath, enu as IEnumerable, dzOptions);
                                break;
                        }
                    else
                        throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                    break;
            }
        }

        private void SetPropFieldGuid(object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (nvn.Type.BaseType)
                    {
                        case InhetoBaseTypes.Guid:
                            acc.SetValue(ref obj, ReadGuidCore(propPath) ?? default);
                            break;
                        case InhetoBaseTypes.String:
                            if (!useCoercion) break;
                            try
                            {
                                var text = ReadStringCore(propPath) ?? throw new InvalidDataException($"Missing GUID text at '{propPath}'.");
                                acc.SetValue(ref obj, text.Length == 0 ? Guid.Empty : new Guid(text));
                            }
                            catch (Exception ex)
                            {
                                if (throwOnTypeMismatch) throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}", ex);
                            }
                            break;
                        case InhetoBaseTypes.ByteArray:
                            if (!useCoercion) break;
                            var gb = ReadByteArrayCore(propPath);
                            if (gb?.Length != 16) throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                            acc.SetValue(ref obj, new Guid(gb));
                            break;
                    }
                    break;
            }
        }

        private void SetPropFieldHalf(object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry entry, IAccessors acc)
        {
            switch (entry.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (entry.Type.BaseType)
                    {
                        case InhetoBaseTypes.Half:
                            acc.SetValue(ref obj, ReadHalfCore(propPath) ?? default);
                            break;

                        // widening → safe (no range error, but lossy)
                        case InhetoBaseTypes.SByte:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Half)(ReadSByteCore(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Byte:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Half)(ReadByteCore(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Int16:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Half)(ReadInt16Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.UInt16:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Half)(ReadUInt16Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Int32:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Half)(ReadInt32Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.UInt32:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Half)(ReadUInt32Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Int64:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Half)(ReadInt64Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.UInt64:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Half)(ReadUInt64Core(propPath) ?? default));
                            break;

                        // floating-point
                        case InhetoBaseTypes.Single:
                            if (!useCoercion) break;
                            var h2f = ReadSingleCore(propPath) ?? default;
                            acc.SetValue(ref obj, (Half)h2f);
                            break;

                        case InhetoBaseTypes.Double:
                            if (!useCoercion) break;
                            var h2d = ReadDoubleCore(propPath) ?? default;
                            acc.SetValue(ref obj, (Half)h2d);
                            break;

                        case InhetoBaseTypes.Decimal:
                            if (!useCoercion) break;
                            var h2m = ReadDecimalCore(propPath) ?? default;
                            acc.SetValue(ref obj, (Half)h2m);
                            break;

                        default:
                            if (throwOnTypeMismatch)
                                throw new InvalidCastException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                            break;
                    }
                    break;
            }
        }

        private void SetPropFieldInt128(object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (nvn.Type.BaseType)
                    {
                        case InhetoBaseTypes.Int128:
                            acc.SetValue(ref obj, ReadInt128Core(propPath) ?? default);
                            break;
                        case InhetoBaseTypes.String:
                            if (!useCoercion) break;
                            try
                            {
                                acc.SetValue(ref obj, Int128.Parse(ReadStringCore(propPath) ?? throw new InvalidDataException($"Missing Int128 text at '{propPath}'.")));
                            }
                            catch (Exception ex)
                            {
                                if (throwOnTypeMismatch) throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}", ex);
                            }
                            break;
                        case InhetoBaseTypes.SByte:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Int128)(ReadSByteCore(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Byte:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Int128)(ReadByteCore(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Int16:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Int128)(ReadInt16Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.UInt16:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Int128)(ReadUInt16Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Int32:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Int128)(ReadInt32Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.UInt32:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Int128)(ReadUInt32Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Int64:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Int128)(ReadInt64Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.UInt64:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Int128)(ReadUInt64Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.UInt128:
                            if (!useCoercion) break;
                            var u128 = ReadUInt128Core(propPath) ?? default;
                            if (u128 > (UInt128)Int128.MaxValue) throw new OverflowException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                            acc.SetValue(ref obj, (Int128)(u128));
                            break;
                    }
                    break;
            }
        }

        private void SetPropFieldInt16(object obj, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry entry, IAccessors acc)
        {
            switch (entry.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (entry.Type.BaseType)
                    {
                        case InhetoBaseTypes.Int16:
                            acc.SetValue(ref obj, ReadInt16Core(propPath) ?? default);
