                            break;

                        case InhetoBaseTypes.Byte:
                            var sh2b = ReadByteCore(propPath) ?? default;
                            acc.SetValue(ref obj, (short)sh2b); // always fits
                            break;

                        case InhetoBaseTypes.UInt16:
