                                else break;
                            }
                            acc.SetValue(ref obj, (short)sh2us);
                            break;

                        case InhetoBaseTypes.Int32:
                            var sh2i = ReadInt32Core(propPath) ?? default;
                            if (sh2i > short.MaxValue || sh2i < short.MinValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (short)sh2i);
                            break;

                        case InhetoBaseTypes.UInt32:
                            var sh2ui = ReadUInt32Core(propPath) ?? default;
                            if (sh2ui > short.MaxValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (short)sh2ui);
                            break;

                        case InhetoBaseTypes.Int64:
                            var sh2l = ReadInt64Core(propPath) ?? default;
                            if (sh2l > short.MaxValue || sh2l < short.MinValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (short)sh2l);
                            break;

                        case InhetoBaseTypes.UInt64:
                            var sh2ul = ReadUInt64Core(propPath) ?? default;
                            if (sh2ul > (ulong)short.MaxValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (short)sh2ul);
                            break;
                    }
                    break;
            }
        }

