        void SetPropFieldIPAddress(ref object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoPromotedType:
                    switch (nvn.Type.PromotedType)
                    {
                        case InhetoPromotedTypes.IPAddress:
                            acc.SetValue(ref obj, ReadIPAddressCore(propPath));
                            break;
                        case InhetoPromotedTypes.IPEndPoint:
                            if (useCoercion)
                                acc.SetValue(ref obj, ReadIPEndPointCore(propPath)?.Address);
                            else
                                throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                            break;
                    }
                    break;
                case InhetoKindMasks.InhetoBaseType:
                    switch (nvn.Type.BaseType)
                    {
                        case InhetoBaseTypes.String:
                            if (!useCoercion) break;
                            try
                            {
                                acc.SetValue(ref obj, IPAddress.Parse(ReadStringCore(propPath) ?? throw new InvalidDataException($"Missing IPAddress text at '{propPath}'.")));
                            }
                            catch (Exception ex)
                            {
                                if (throwOnTypeMismatch) throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}", ex);
                            }
                            break;
                    }
                    break;
            }
        }

