        void SetPropFieldListString(object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc, DeserializationOptions dzOptions)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (nvn.Type.BaseType)
                    {
                        case InhetoBaseTypes.String:
                            if (!useCoercion)
                            {
                                if (throwOnTypeMismatch)
                                    throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                                else
                                    break;
                            }

                            var lss = acc.GetValue(obj) as List<string>;
                            if (lss is null)
                                acc.SetValue(ref obj, ReadStringCore(propPath));
                            else
                                ReadStringListCore(propPath, lss);

                            acc.SetValue(ref obj, lss);
                            break;
                        case InhetoBaseTypes.ListString:
                            var lsls = acc.GetValue(obj) as List<string>;
                            if (lsls is null)
                                acc.SetValue(ref obj, ReadStringListCore(propPath));
                            else
                                ReadStringListCore(propPath, lsls);

                            break;
                    }
                    break;
                case InhetoKindMasks.InhetoPromotedType:
                    if (!useCoercion)
                    {
                        if (throwOnTypeMismatch)
                            throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                        else
                            break;
                    }

                    switch (nvn.Type.PromotedType)
                    {
                        case InhetoPromotedTypes.StringCollection:
                            {

                                var nvc = acc.GetValue(obj) as List<string?>;
                                var doSetValue = nvc is null;
                                nvc ??= new List<string?>();

                                var nvnIndex = nvn.Index;
                                var dCount = nvn.ValueOffset;
                                for (int i = 0; i < dCount; i++)
                                {
                                    nvc.Add(ReadMaterializedString($"{propPath}#{i}"));
                                }
                                if (doSetValue) acc.SetValue(ref obj, nvc);
                            }
                            break;
                    }
                    break;
                case InhetoKindMasks.InhetoCollectionType:
                    if (!useCoercion)
                    {
                        if (throwOnTypeMismatch)
                            throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                        else
                            break;
                    }
                    switch (nvn.Type.CollectionInfo.CollectionType)
                    {
                        case InhetoCollectionTypes.List:
                        case InhetoCollectionTypes.Queue:
                        case InhetoCollectionTypes.ConcurrentQueue:
                        case InhetoCollectionTypes.Stack:
                        case InhetoCollectionTypes.ConcurrentStack:
                        case InhetoCollectionTypes.ObservableCollection:
                        case InhetoCollectionTypes.ConcurrentBag:
                        case InhetoCollectionTypes.SortedSet:
                        case InhetoCollectionTypes.HashSet:
                            if (nvn.Type.CollectionInfo.ValueType.Kind is InhetoKindMasks.InhetoBaseType or InhetoKindMasks.InhetoNullableBaseType &&
                                (nvn.Type.CollectionInfo.ValueType.Kind == InhetoKindMasks.InhetoNullableBaseType
                                    ? nvn.Type.CollectionInfo.ValueType.NullableBaseType
                                    : nvn.Type.CollectionInfo.ValueType.BaseType) is
                                    InhetoBaseTypes.ComplexType or InhetoBaseTypes.String or InhetoBaseTypes.Byte or InhetoBaseTypes.SByte or
                                    InhetoBaseTypes.Int16 or InhetoBaseTypes.UInt16 or InhetoBaseTypes.Int32 or InhetoBaseTypes.UInt32 or
                                    InhetoBaseTypes.Int64 or InhetoBaseTypes.UInt64 or InhetoBaseTypes.Int128 or InhetoBaseTypes.UInt128 or
                                    InhetoBaseTypes.Half or InhetoBaseTypes.Single or InhetoBaseTypes.Double or InhetoBaseTypes.Decimal or
                                    InhetoBaseTypes.DateOnly or InhetoBaseTypes.DateTime or InhetoBaseTypes.TimeOnly or InhetoBaseTypes.TimeSpan or
                                    InhetoBaseTypes.Guid or InhetoBaseTypes.DateTimeOffset or InhetoBaseTypes.Version or InhetoBaseTypes.Uri)
                            {
                                var destination = acc.GetValue(obj) as List<string>;
                                if (destination is null && acc.ReadOnly) break;
                                var result = ReadProjectedStringList(nvn, propPath, destination, dzOptions);
                                if (destination is null && result is not null) acc.SetValue(ref obj, result);
                            }
                            break;
                    }
                    break;
            }
        }

