        void SetPropFieldNameValueCollection(ref object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoPromotedType:
                    switch (nvn.Type.PromotedType)
                    {
                        case InhetoPromotedTypes.NameValueCollection:
                            var nvc = acc.GetValue(obj) as NameValueCollection;
                            if (nvc is null)
                            {
                                nvc = ReadNameValueCollectionCore(propPath, nvc);
                                acc.SetValue(ref obj, nvc);
                            }
                            else
                                ReadNameValueCollectionCore(propPath, nvc);

                            break;
                    }
                    break;
                case InhetoKindMasks.InhetoCollectionType:
                    if (!useCoercion)
                    {
                        if (throwOnTypeMismatch)
                            throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}");
                        else
                            break;
                    }

                    switch (nvn.Type.CollectionInfo.CollectionType)
                    {
                        case InhetoCollectionTypes.StringKeyDictionary:
                            if (nvn.Type.CollectionInfo.KeyType.BaseType == InhetoBaseTypes.String && nvn.Type.CollectionInfo.ValueType.BaseType == InhetoBaseTypes.String)
                            {
                                var nvc = acc.GetValue(obj) as NameValueCollection;
                                var doSetValue = nvc is null;
                                nvc ??= new NameValueCollection();
                                var nvnIndex = nvn.Index;
                                var dCount = nvn.ValueOffset;
                                var sib = nvn.FirstChild(NameHeaderEntry.EntryTypes.KeyString);
                                for (int i = 0; i < dCount; i++)
                                {
                                    nvc.Add(sib.CleanName, ReadStringCore($"{propPath}!{sib.Name}"));
                                    sib = sib.NextSibling(NameHeaderEntry.EntryTypes.KeyString);
                                    if (sib.IsEmpty) break;
                                }
                                if (doSetValue) acc.SetValue(ref obj, nvc);
                                break;
                            }
                            break;
                    }
                    break;
            }
        }

