        private void SetPropFieldRune(object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry entry, IAccessors acc)
        {
            switch (entry.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (entry.Type.BaseType)
                    {
                        case InhetoBaseTypes.Rune:
                            acc.SetValue(ref obj, ReadRuneCore(propPath) ?? default);
                            break;
                        case InhetoBaseTypes.String:
                            if (!useCoercion) break;
                            var cstr = ReadStringCore(propPath) ?? "";
                            if (cstr.Length == 0) break;
                            acc.SetValue(ref obj, cstr.EnumerateRunes().FirstOrDefault());
                            break;
                        case InhetoBaseTypes.Char:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (Rune)(ReadCharCore(propPath).GetValueOrDefault()));
                            break;
                        case InhetoBaseTypes.SByte:
                            if (!useCoercion) break;
                            if (Rune.TryCreate((int)ReadSByteCore(propPath).GetValueOrDefault(), out Rune sbrune))
                                acc.SetValue(ref obj, sbrune);
                            else if (throwOnTypeMismatch)
                                throw new InvalidCastException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                            break;
                        case InhetoBaseTypes.Byte:
                            if (!useCoercion) break;
                            if (Rune.TryCreate((uint)ReadByteCore(propPath).GetValueOrDefault(), out Rune brune))
                                acc.SetValue(ref obj, brune);
                            else if (throwOnTypeMismatch)
                                throw new InvalidCastException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                            break;
                        case InhetoBaseTypes.Int16:
                            if (!useCoercion) break;
                            if (Rune.TryCreate((int)ReadInt16Core(propPath).GetValueOrDefault(), out Rune shrune))
                                acc.SetValue(ref obj, shrune);
                            else if (throwOnTypeMismatch)
                                throw new InvalidCastException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                            break;
                        case InhetoBaseTypes.UInt16:
                            if (!useCoercion) break;
                            if (Rune.TryCreate((uint)ReadUInt16Core(propPath).GetValueOrDefault(), out Rune ushrune))
                                acc.SetValue(ref obj, ushrune);
                            else if (throwOnTypeMismatch)
                                throw new InvalidCastException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                            break;
                        case InhetoBaseTypes.Int32:
                            if (!useCoercion) break;
                            if (Rune.TryCreate(ReadInt32Core(propPath).GetValueOrDefault(), out Rune irune))
                                acc.SetValue(ref obj, irune);
                            else if (throwOnTypeMismatch)
                                throw new InvalidCastException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                            break;
                        case InhetoBaseTypes.UInt32:
                            if (!useCoercion) break;
                            if (Rune.TryCreate(ReadUInt32Core(propPath).GetValueOrDefault(), out Rune uirune))
                                acc.SetValue(ref obj, uirune);
                            else if (throwOnTypeMismatch)
                                throw new InvalidCastException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                            break;
                        default:
                            if (throwOnTypeMismatch) throw new InvalidCastException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                            break;
                    }
                    break;
            }
        }

        private void SetPropFieldSByte(object obj, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry entry, IAccessors acc)
        {
            switch (entry.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (entry.Type.BaseType)
                    {
                        case InhetoBaseTypes.SByte:
                            acc.SetValue(ref obj, ReadSByteCore(propPath) ?? default);
                            break;
                        case InhetoBaseTypes.Byte:
                            var sb2by = ReadByteCore(propPath) ?? default;
                            if (sb2by > sbyte.MaxValue)
                                if (throwOnTypeMismatch) throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else
                                    break;
                            acc.SetValue(ref obj, (sbyte)sb2by);
                            break;
                        case InhetoBaseTypes.Int16:
                            var sb2sh = ReadInt16Core(propPath) ?? default;
                            if (sb2sh > sbyte.MaxValue || sb2sh < sbyte.MinValue)
                                if (throwOnTypeMismatch) throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else
                                    break;
                            acc.SetValue(ref obj, (sbyte)sb2sh);
                            break;
                        case InhetoBaseTypes.UInt16:
                            var sb2ush = ReadUInt16Core(propPath) ?? default;
                            if (sb2ush > sbyte.MaxValue)
                                if (throwOnTypeMismatch) throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else
                                    break;
                            acc.SetValue(ref obj, (sbyte)sb2ush);
                            break;
                        case InhetoBaseTypes.Int32:
                            var sb2i = ReadInt32Core(propPath) ?? default;
                            if (sb2i > sbyte.MaxValue || sb2i < sbyte.MinValue)
                                if (throwOnTypeMismatch) throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else
                                    break;
                            acc.SetValue(ref obj, (sbyte)sb2i);
                            break;
                        case InhetoBaseTypes.UInt32:
                            var sb2ui = ReadUInt32Core(propPath) ?? default;
                            if (sb2ui > sbyte.MaxValue)
                                if (throwOnTypeMismatch) throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else
                                    break;
                            acc.SetValue(ref obj, (sbyte)sb2ui);
                            break;
                        case InhetoBaseTypes.Int64:
                            var sb2l = ReadInt64Core(propPath) ?? default;
                            if (sb2l > sbyte.MaxValue || sb2l < sbyte.MinValue)
                                if (throwOnTypeMismatch) throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else
                                    break;
                            acc.SetValue(ref obj, (sbyte)sb2l);
                            break;
                        case InhetoBaseTypes.UInt64:
                            var sb2ul = ReadUInt64Core(propPath) ?? default;
                            if (sb2ul > (ulong)sbyte.MaxValue)
                                if (throwOnTypeMismatch) throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else
                                    break;
                            acc.SetValue(ref obj, (sbyte)sb2ul);
                            break;
                    }
                    break;
            }
        }

        void SetPropFieldSecureString(ref object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoPromotedType:
                    switch (nvn.Type.PromotedType)
