        private void SetPropFieldSingle(object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry entry, IAccessors acc)
        {
            switch (entry.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (entry.Type.BaseType)
                    {
                        case InhetoBaseTypes.Single:
                            acc.SetValue(ref obj, ReadSingleCore(propPath) ?? default);
                            break;

                        // widening → safe (no range error, but lossy)
                        case InhetoBaseTypes.SByte:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (float)(ReadSByteCore(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Byte:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (float)(ReadByteCore(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Int16:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (float)(ReadInt16Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.UInt16:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (float)(ReadUInt16Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Int32:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (float)(ReadInt32Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.UInt32:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (float)(ReadUInt32Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Int64:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (float)(ReadInt64Core(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.UInt64:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (float)(ReadUInt64Core(propPath) ?? default));
                            break;

                        // floating-point
                        case InhetoBaseTypes.Half:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (float)(ReadHalfCore(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Double:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (float)(ReadDoubleCore(propPath) ?? default));
                            break;
                        case InhetoBaseTypes.Decimal:
                            if (!useCoercion) break;
                            acc.SetValue(ref obj, (float)(ReadDecimalCore(propPath) ?? default));
                            break;

                        default:
                            if (throwOnTypeMismatch)
                                throw new InvalidCastException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                            break;
                    }
                    break;
            }
        }

