                            break;
                        case InhetoPromotedTypes.StringBuilder:
                            acc.SetValue(ref obj, (ReadStringBuilderCore(propPath) ?? throw new InvalidDataException($"Missing StringBuilder string-projection value at '{propPath}'.")).ToString());
                            break;
                        case InhetoPromotedTypes.TimeZoneInfo:
                            acc.SetValue(ref obj, ReadStringCore(propPath) ?? throw new InvalidDataException($"Missing TimeZoneInfo string-projection text at '{propPath}'."));
                            break;
                        case InhetoPromotedTypes.Type:
                            acc.SetValue(ref obj, ReadStringCore(propPath) ?? throw new InvalidDataException($"Missing Type string-projection text at '{propPath}'."));
