        void SetPropFieldStringBuilder(ref object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoPromotedType:
                    switch (nvn.Type.PromotedType)
                    {
                        case InhetoPromotedTypes.StringBuilder:
                            acc.SetValue(ref obj, ReadStringBuilderCore(propPath));
                            break;
                    }
                    break;
                case InhetoKindMasks.InhetoBaseType:
                    switch (nvn.Type.BaseType)
                    {
                        case InhetoBaseTypes.String:
                            if (!useCoercion) break;
                            try
                            {
                                acc.SetValue(ref obj, new StringBuilder(ReadStringCore(propPath) ?? throw new InvalidDataException($"Missing StringBuilder conversion text at '{propPath}'.")));
                            }
                            catch (Exception ex)
                            {
                                if (throwOnTypeMismatch) throw new InvalidCastException($"Cannot coerce {nvn.Type} to {projectedTypeInfo.BaseType}", ex);
                            }
                            break;
