        void SetPropFieldTimeZoneInfo(ref object obj, bool useCoercion, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry nvn, IAccessors acc)
        {
            switch (nvn.Kind)
            {
                case InhetoKindMasks.InhetoPromotedType:
                    switch (nvn.Type.PromotedType)
                    {
                        case InhetoPromotedTypes.TimeZoneInfo:
