        private void SetPropFieldUInt16(object obj, bool throwOnTypeMismatch, string propPath, InhetoTypeInfo projectedTypeInfo, NameHeaderEntry entry, IAccessors acc)
        {
            switch (entry.Kind)
            {
                case InhetoKindMasks.InhetoBaseType:
                    switch (entry.Type.BaseType)
                    {
                        case InhetoBaseTypes.UInt16:
                            acc.SetValue(ref obj, ReadUInt16Core(propPath) ?? default);
                            break;

                        case InhetoBaseTypes.SByte:
                            var us2sb = ReadSByteCore(propPath) ?? default;
                            if (us2sb < 0)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (ushort)us2sb);
                            break;

                        case InhetoBaseTypes.Byte:
                            var us2b = ReadByteCore(propPath) ?? default;
                            acc.SetValue(ref obj, (ushort)us2b); // always fits
                            break;

                        case InhetoBaseTypes.Int16:
                            var us2sh = ReadInt16Core(propPath) ?? default;
                            if (us2sh < 0)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (ushort)us2sh);
                            break;

                        case InhetoBaseTypes.Int32:
                            var us2i = ReadInt32Core(propPath) ?? default;
                            if (us2i > ushort.MaxValue || us2i < ushort.MinValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (ushort)us2i);
                            break;

                        case InhetoBaseTypes.UInt32:
                            var us2ui = ReadUInt32Core(propPath) ?? default;
                            if (us2ui > ushort.MaxValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (ushort)us2ui);
                            break;

                        case InhetoBaseTypes.Int64:
                            var us2l = ReadInt64Core(propPath) ?? default;
                            if (us2l > ushort.MaxValue || us2l < ushort.MinValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (ushort)us2l);
                            break;

                        case InhetoBaseTypes.UInt64:
                            var us2ul = ReadUInt64Core(propPath) ?? default;
                            if (us2ul > ushort.MaxValue)
                            {
                                if (throwOnTypeMismatch)
                                    throw new OverflowException($"Cannot coerce {entry.Type} to {projectedTypeInfo.BaseType}");
                                else break;
                            }
                            acc.SetValue(ref obj, (ushort)us2ul);
                            break;
                    }
                    break;
            }
        }

