        //------ Public Methods -----
        /// <summary>
        /// Tests whether a property path resolves to an encoded name entry, including entries whose stored value is null.<br/>
        /// </summary>
        /// <param name="propPath">Logical Inheto member path; use the empty path for the root where supported and numbered tokens for collection elements.<br/></param>
        /// <returns>True when the documented predicate is satisfied; otherwise false.<br/></returns>
        private bool PropExistsCore(string propPath)
        {
            if (TryResolvePreparedEntryIndex(propPath, out uint entryIndex))
                return entryIndex != 0;
            return !GetNameEntryFromPropPath(propPath).IsEmpty;
        }

        /// <summary>
        /// Reports whether a logical property path or one of its registered equivalents exists in this payload.<br/>
        /// The exact requested path retains precedence over alias fallbacks.<br/>
        /// </summary>
        /// <param name="propPath">Logical property path to inspect.<br/></param>
        /// <param name="dzOptions">Read policy containing optional property aliases.<br/></param>
        /// <returns><see langword="true"/> when an exact or aliased stored member exists; otherwise <see langword="false"/>.<br/></returns>
        private bool PropExistsCore(string propPath, DeserializationOptions? dzOptions)
            => !GetNameEntryFromPropPath(propPath, dzOptions, out _).IsEmpty;

        internal Array? ReadArrayOf(Type elementType, string propPath, DeserializationOptions dzOptions, bool useCoercion = false)
        {
            var key = elementType;
            var fn = _cacheReadArrayOf.GetOrAdd(key, static t =>
            {
                // Make the closed generic method
                var open = typeof(InhetoBinary).Method(nameof(ReadArrayOf), new[] { typeof(string), typeof(DeserializationOptions), typeof(bool) });

                var m = open.MakeGenericMethod(t);

                // Build (Deserializer self, string p, DeserializationOptions o, bool c) => self.ReadArrayOf<T>(p, o, c)
                var self = Expression.Parameter(typeof(InhetoBinary), "self");
                var p = Expression.Parameter(typeof(string), "p");
                var o = Expression.Parameter(typeof(DeserializationOptions), "o");
                var c = Expression.Parameter(typeof(bool), "c");

                var call = Expression.Call(self, m, p, o, c);
                var lambda = Expression.Lambda<Func<InhetoBinary, string, DeserializationOptions, bool, Array?>>(
                    Expression.Convert(call, typeof(Array)), self, p, o, c);

                return lambda.Compile();
            });

            return fn(this, propPath, dzOptions, useCoercion);
        }

        /// <summary>
        /// Reads the encoded BigInteger representation at a property path; missing or explicit-null entries return null. Use ReadPropAs for general requested-type conversion rather than assuming this native reader accepts every wire shape.<br/>
        /// </summary>
        /// <param name="propPath">Logical Inheto member path; use the empty path for the root where supported and numbered tokens for collection elements.<br/></param>
        /// <returns>Native typed value, or null for a missing or explicit-null entry.<br/></returns>
        private BigInteger? ReadBigIntegerCore(string propPath)
        {
            var entry = GetNameEntryFromPropPath(propPath);
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Unknown) return default;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Null) return default;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.DuplicateRef)
            {
                entry = NameHeaderEntry.CreateBorrowed(stream, entry.ValueOffset, entry.Name);
            }

            return (BigInteger)GetOrAddCached(entry.Index, k =>
            {
                stream.Position = entry.ValueOffset;
                return stream.ReadBigInteger();
            });

        }

        /// <summary>
        /// Reads the encoded BitArray representation at a property path; missing or explicit-null entries return null. Use ReadPropAs for general requested-type conversion rather than assuming this native reader accepts every wire shape.<br/>
        /// </summary>
        /// <param name="propPath">Logical Inheto member path; use the empty path for the root where supported and numbered tokens for collection elements.<br/></param>
        /// <returns>Native typed value, or null for a missing or explicit-null entry.<br/></returns>
        private BitArray? ReadBitArrayCore(string propPath)
        {
            var entry = GetNameEntryFromPropPath(propPath);
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Unknown) return default;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Null) return default;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.DuplicateRef)
            {
                entry = NameHeaderEntry.CreateBorrowed(stream, entry.ValueOffset, entry.Name);
            }

            return (BitArray)GetOrAddCached(entry.Index, k =>
            {
                stream.Position = entry.ValueOffset;
                return stream.ReadBitArray();
            });
        }

        /// <summary>
        /// Reads the encoded Boolean representation at a property path; missing or explicit-null entries return null. Use ReadPropAs for general requested-type conversion rather than assuming this native reader accepts every wire shape.<br/>
        /// </summary>
        /// <param name="propPath">Logical Inheto member path; use the empty path for the root where supported and numbered tokens for collection elements.<br/></param>
        /// <returns>Native typed value, or null for a missing or explicit-null entry.<br/></returns>
        private bool? ReadBooleanCore(string propPath)
        {
            var nvn = GetInlineNavigation(propPath);
            if (nvn.Kind == InhetoKindMasks.InhetoBaseType && nvn.Type.BaseType == InhetoBaseTypes.Unknown) return null;
            if (nvn.Kind == InhetoKindMasks.InhetoBaseType && nvn.Type.BaseType == InhetoBaseTypes.Null) return null;

            // value was inlined in valueOffset
            return nvn.ValueOffset != 0;
        }

        /// <summary>
        /// Reads the encoded Byte representation at a property path; missing or explicit-null entries return null. Use ReadPropAs for general requested-type conversion rather than assuming this native reader accepts every wire shape.<br/>
        /// </summary>
        /// <param name="propPath">Logical Inheto member path; use the empty path for the root where supported and numbered tokens for collection elements.<br/></param>
        /// <returns>Native typed value, or null for a missing or explicit-null entry.<br/></returns>
        private byte? ReadByteCore(string propPath)
        {
            var nvn = GetInlineNavigation(propPath);
            if ((nvn.Type.BaseType | nvn.Type.EnumType) == InhetoBaseTypes.Unknown) return null;
            if ((nvn.Type.BaseType | nvn.Type.EnumType) == InhetoBaseTypes.Null) return null;
            // value was inlined in valueOffset
            return (byte)nvn.ValueOffset;
        }

        /// <summary>
        /// Reads the encoded ByteArray representation at a property path; missing or explicit-null entries return null. Use ReadPropAs for general requested-type conversion rather than assuming this native reader accepts every wire shape.<br/>
        /// </summary>
        /// <param name="propPath">Logical Inheto member path; use the empty path for the root where supported and numbered tokens for collection elements.<br/></param>
        /// <returns>Native typed value, or null for a missing or explicit-null entry.<br/></returns>
        /// <remarks>Native payload reads allocate detached byte storage; these are not zero-copy slices of the source stream.<br/></remarks>
        private byte[]? ReadByteArrayCore(string propPath)
        {
            var entry = GetNameEntryFromPropPath(propPath);
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Unknown) return default;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Null) return default;
            bool copy = entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.DuplicateValue;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && (entry.Type.BaseType == InhetoBaseTypes.DuplicateRef || copy))
            {
                entry = NameHeaderEntry.CreateBorrowed(stream, entry.ValueOffset, entry.Name);
            }

            var ret = GetOrAddCached(entry.Index, k =>
            {
                stream.Position = entry.ValueOffset;
                return stream.ReadBytesWithByteLength();
            });
            return materializationOperationDepth != 0 && copy ? CloneIfMutable(ret) : ret;


        }
        /// <summary>
        /// Reads the encoded MemoryByte representation at a property path; missing or explicit-null entries return null. Use ReadPropAs for general requested-type conversion rather than assuming this native reader accepts every wire shape.<br/>
        /// </summary>
        /// <param name="propPath">Logical Inheto member path; use the empty path for the root where supported and numbered tokens for collection elements.<br/></param>
        /// <returns>Native typed value, or null for a missing or explicit-null entry.<br/></returns>
        /// <remarks>Native payload reads allocate detached byte storage; these are not zero-copy slices of the source stream.<br/></remarks>
        private Memory<byte>? ReadMemoryByteCore(string propPath)
        {
            var entry = GetNameEntryFromPropPath(propPath);
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Unknown) return default;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Null) return default;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.DuplicateRef)
            {
