            if (entry.Kind == InhetoKindMasks.InhetoBaseType &&
                entry.Type.BaseType is InhetoBaseTypes.CustomProp or InhetoBaseTypes.CustomType &&
                originalBaseType != InhetoBaseTypes.DuplicateValue)
            {
                if (TryReadCustomValue(entry, propPath, propPath, originalBaseType == InhetoBaseTypes.DuplicateRef, null, dzOptions, out var customValue))
