                                                case InhetoBaseTypes.Quaternion:
                                                    FillQuaternionList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoBaseTypes.Plane:
                                                    FillPlaneList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoBaseTypes.Matrix3x2:
                                                    FillMatrix3x2List(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoBaseTypes.Matrix4x4:
                                                    FillMatrix4x4List(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoBaseTypes.BigInteger:
                                                    FillBigIntegerList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoBaseTypes.ByteArray:
                                                    FillByteArrayList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoBaseTypes.ListString:
                                                    FillListStringList(entry, ret as IEnumerable, true, false);
                                                    break;

                                            }
                                            break;
                                        case InhetoKindMasks.InhetoPromotedType:
                                            switch (entry.Type.CollectionInfo.ValueType.PromotedType)
                                            {
                                                case InhetoPromotedTypes.Enum:
                                                    switch (entry.Type.CollectionInfo.ValueType.EnumType)
                                                    {
                                                        case InhetoBaseTypes.SByte:
                                                            FillEnumList<sbyte>(entry, ret as IEnumerable, true, false);
                                                            break;
                                                        case InhetoBaseTypes.Byte:
                                                            FillEnumList<byte>(entry, ret as IEnumerable, true, false);
                                                            break;
                                                        case InhetoBaseTypes.Int16:
                                                            FillEnumList<short>(entry, ret as IEnumerable, true, false);
                                                            break;
                                                        case InhetoBaseTypes.UInt16:
                                                            FillEnumList<ushort>(entry, ret as IEnumerable, true, false);
                                                            break;
                                                        case InhetoBaseTypes.Int32:
                                                            FillEnumList<int>(entry, ret as IEnumerable, true, false);
                                                            break;
                                                        case InhetoBaseTypes.UInt32:
                                                            FillEnumList<uint>(entry, ret as IEnumerable, true, false);
                                                            break;
                                                        case InhetoBaseTypes.Int64:
                                                            FillEnumList<long>(entry, ret as IEnumerable, true, false);
                                                            break;
                                                        case InhetoBaseTypes.UInt64:
                                                            FillEnumList<ulong>(entry, ret as IEnumerable, true, false);
                                                            break;
                                                    }
                                                    break;
                                                case InhetoPromotedTypes.CultureInfo:
                                                    FillCultureInfoList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoPromotedTypes.IPAddress:
                                                    // need to handle ReadOnlyIPAddress
                                                    FillIPAddressList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoPromotedTypes.IPEndPoint:
                                                    FillIPEndPointList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoPromotedTypes.MailAddress:
                                                    FillMailAddressList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoPromotedTypes.MemoryByte:
                                                    FillMemoryByteList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoPromotedTypes.MemoryStream:
                                                    FillMemoryStreamList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoPromotedTypes.ReadOnlyMemoryByte:
                                                    FillReadOnlyMemoryByteList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoPromotedTypes.StringBuilder:
                                                    FillStringBuilderList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoPromotedTypes.TimeZoneInfo:
                                                    FillTimeZoneInfoList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoPromotedTypes.Regex:
                                                    FillRegexList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoPromotedTypes.SecureString:
                                                    FillSecureStringList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoPromotedTypes.Type:
                                                    FillTypeList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoPromotedTypes.NameValueCollection:
                                                    FillNameValueCollectionList(entry, ret as IEnumerable, true, false);
                                                    break;
                                                case InhetoPromotedTypes.StringCollection:
                                                    FillStringCollectionList(entry, ret as IEnumerable, true, false);
                                                    break;
                                            }
                                            break;

                                    }

                                }
                                break;
                        }
                        break;
                }

                return ret;

                Array? ReturnArray<T>(string propPath, NameHeaderEntry nvn, uint acount)
                {
                    var arrayOfT = CreateJaggedArray<T>(nvn.Type.ArrayInfo.Depth, (int)acount);

                    for (int i = 0; i < acount; i++)
                        arrayOfT.SetValue(ReadPropInternal($"{propPath}#{i}", dzOptions) ?? default, i);
                    {
                        return arrayOfT;
                    }
                }

            }, preserveIdentity: materializationOperationDepth != 0 && entry.Kind == InhetoKindMasks.InhetoCollectionType);
            return materializationOperationDepth != 0 && originalBaseType == InhetoBaseTypes.DuplicateValue && cached is Array or List<string> or NameValueCollection or StringCollection or MemoryStream or StringBuilder
                ? CloneIfMutable(cached) : cached;
        }

        /// <summary>
        /// Reads a typed child using its caller's existing materialization operation and reference identity.<br/>
        /// Internal recursion must use this core instead of the public independent-operation entry point.<br/>
        /// </summary>
        /// <typeparam name="T">Requested child shape.<br/></typeparam>
        /// <param name="propPath">Requested progressive child path.<br/></param>
        /// <param name="dzOptions">Current operation's decoding options.<br/></param>
        /// <returns>The materialized child, including an intentional null.<br/></returns>
        private T? ReadMaterializedAs<T>(string propPath, DeserializationOptions? dzOptions = null) => ReadMaterializedAs<T>(default, propPath, dzOptions);

        /// <summary>
        /// Dispatches a runtime-selected child type within the current operation without nesting its value cache.<br/>
        /// The compiled delegate targets the private generic core; only immutable type dispatch is cached.<br/>
        /// </summary>
        /// <param name="returnType">Requested CLR child type.<br/></param>
        /// <param name="propPath">Progressive child path.<br/></param>
        /// <param name="dzOptions">Current operation's decoding options.<br/></param>
        /// <returns>The materialized child or intentional null.<br/></returns>
        private object? ReadMaterializedAs(Type returnType, string propPath, DeserializationOptions? dzOptions = null)
        {
            dzOptions ??= deserializationOptions;
            var key = returnType;

            var del = _cacheReadPropAs.GetOrAdd(key, k =>
            {
                // This exact private overload is an internal contract, checked only during cache construction.
                var open = typeof(InhetoBinary).GetMethod(nameof(ReadMaterializedAs), BindingFlags.Instance | BindingFlags.NonPublic,
                    new[] { typeof(string), typeof(DeserializationOptions) })
                    ?? throw new MissingMethodException(typeof(InhetoBinary).FullName, nameof(ReadMaterializedAs) + "<T>(string, DeserializationOptions)");

                var closed = open.MakeGenericMethod(returnType);

                // build expression: (InhetoBinary inst, string p, DeserializationOptions dz) => (object)inst.ReadMaterializedAs<T>(p, dz)
                var instParam = Expression.Parameter(typeof(InhetoBinary), "inst");
                var pathParam = Expression.Parameter(typeof(string), "propPath");
                var optParam = Expression.Parameter(typeof(DeserializationOptions), "dzOptions");

                var call = Expression.Call(instParam, closed, pathParam, optParam);
                var boxed = Expression.Convert(call, typeof(object));

                var lambda = Expression.Lambda<Func<InhetoBinary, string, DeserializationOptions, object?>>(
                    boxed, instParam, pathParam, optParam);

                return lambda.Compile();
            });

            return del(this, propPath, dzOptions);
        }

        /// <summary>
        /// Reads through ReadPropAs and returns the result only when its non-null runtime type exactly equals the requested type. Assignable derived results and null results instead produce default(T).<br/>
        /// </summary>
        /// <typeparam name="T">CLR type used by this operation; result conversion or exact-type registration follows the documented contract.<br/></typeparam>
        /// <param name="propPath">Logical Inheto member path; use the empty path for the root where supported and numbered tokens for collection elements.<br/></param>
        /// <param name="dzOptions">Optional deserialization policy; see this overload&apos;s remarks for forwarding limitations.<br/></param>
        /// <returns>Exactly typed non-null result, or default(T) for null/missing/different-runtime-type results.<br/></returns>
        public T? ReadPropExact<T>(string propPath, DeserializationOptions? dzOptions = null)
        {
            var ret = ReadPropAs<T>(propPath, dzOptions);
            if (ret is not null && ret.GetType() == typeof(T)) return ret;
            return default;

        }

        /// <summary>
        /// Fills the supplied destination in an independent operation, retaining existing destination/member semantics.<br/>
        /// Earlier create/fill/read results cannot bypass this destination; operation values are released even on failure.<br/>
        /// A reentrant public fill has an isolated value cache and restores its caller's cache and cursor.<br/>
        /// </summary>
        /// <param name="instance">Developer-owned destination; collection members retain their existing addition policy.<br/></param>
        /// <param name="propPath">Encoded shape to apply to the destination.<br/></param>
        /// <param name="dzOptions">Applicable activation, projection and codec options.<br/></param>
        /// <typeparam name="T">Developer-selected destination type.<br/></typeparam>
        public void ReadPropOnto<T>(T instance, string propPath, DeserializationOptions? dzOptions = null)
        {
            var operation = BeginMaterializationOperation(dzOptions);
            try { ReadMaterializedAs<T>(instance, propPath, dzOptions); }
            finally { EndMaterializationOperation(operation); }
        }

        /// <summary>
        /// Fills an existing instance through the dispatch for its declared CLR type, applying the effective deserialization policy. This updates the instance in place and does not return a replacement root.<br/>
        /// </summary>
        /// <param name="instanceType">Exact CLR owner type used to select the matching compiled dispatch.<br/></param>
        /// <param name="instance">Compatible owner instance to read or mutate; a by-reference argument preserves value-type changes.<br/></param>
        /// <param name="propPath">Logical Inheto member path; use the empty path for the root where supported and numbered tokens for collection elements.<br/></param>
        /// <param name="dzOptions">Optional deserialization policy; see this overload&apos;s remarks for forwarding limitations.<br/></param>
        public void ReadPropOnto(Type instanceType, object instance, string propPath, DeserializationOptions? dzOptions = null)
        {
            if (instanceType == null)
                throw new ArgumentNullException(nameof(instanceType));
            if (instance == null)
                throw new ArgumentNullException(nameof(instance));

            dzOptions ??= deserializationOptions;

            var fn = CacheReadPropOnto.GetValue(instanceType, FillDispatch.Create);

            fn(this, instance, propPath, dzOptions);
        }

