RedoAfterDupe:
            if (nvn.Kind == InhetoKindMasks.InhetoBaseType && nvn.Type.BaseType == InhetoBaseTypes.Unknown) return default;
            if (nvn.Kind == InhetoKindMasks.InhetoBaseType && nvn.Type.BaseType == InhetoBaseTypes.Null) return default;
