        /// <summary>
        /// Reads a Version while retaining its original two-, three- or four-component shape.<br/>
        /// The wire always stores four integers; -1 marks an unspecified trailing Build or Revision.<br/>
        /// Invalid negative components or a Revision without a Build throw instead of fabricating a Version.<br/>
        /// Missing/null paths, duplicate handling and the existing value cache retain their current semantics.<br/>
        /// </summary>
        /// <param name="propPath">Progressive property path to the encoded Version value.<br/></param>
        /// <returns>The materialized Version, or null for an absent/null path.<br/></returns>
        private Version? ReadVersionCore(string propPath)
        {
            var entry = GetNameEntryFromPropPath(propPath);
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Unknown) return default;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && entry.Type.BaseType == InhetoBaseTypes.Null) return default;
            if (entry.Kind == InhetoKindMasks.InhetoBaseType && (entry.Type.BaseType == InhetoBaseTypes.DuplicateValue || entry.Type.BaseType == InhetoBaseTypes.DuplicateRef))
            {
                entry = NameHeaderEntry.CreateBorrowed(stream, entry.ValueOffset, entry.Name);
            }

            return (Version)GetOrAddCached(entry.Index, k =>
            {
                stream.Position = entry.ValueOffset;
                int major = stream.Read7BitEncodedInt();
                int minor = stream.Read7BitEncodedInt();
                int build = stream.Read7BitEncodedInt();
                int revision = stream.Read7BitEncodedInt();
                if (major < 0 || minor < 0 || build < -1 || revision < -1 || (build == -1 && revision != -1))
                    throw new InvalidDataException("Invalid encoded Version components.");
                return build == -1 ? new Version(major, minor)
                    : revision == -1 ? new Version(major, minor, build)
                    : new Version(major, minor, build, revision);

            });
        }

        /// <summary>
        /// Materializes the root into the requested CLR type using one operation-local identity scope, applying configured activators, aliases and root materializers. Developer hooks may run; this is not a concurrent-use operation on the same reader.<br/>
        /// </summary>
        /// <typeparam name="T">CLR type used by this operation; result conversion or exact-type registration follows the documented contract.<br/></typeparam>
        /// <param name="dzOptions">Optional deserialization policy; see this overload&apos;s remarks for forwarding limitations.<br/></param>
        /// <returns>Materialized root value, possibly null when the source or an activator yields null; conversion and developer-code failures may throw.<br/></returns>
        public T? ToObject<T>(DeserializationOptions? dzOptions = null)
        {
            var operation = BeginMaterializationOperation();
            try
            {
                DeserializationOptions effectiveOptions = deserializationOptions.PrepareRootOptions(
                    typeof(T),
                    materializationContext,
                    dzOptions ?? deserializationOptions);
                materializationOptions = effectiveOptions;
                object? value;
                if (typeof(T) == typeof(object))
                    value = ReadPropInternal("", effectiveOptions);
                else
                    value = ReadMaterializedAs<T>("", effectiveOptions);
                value = deserializationOptions.ApplyRootMaterializers(
                    this,
                    value,
                    typeof(T),
                    materializationContext,
                    effectiveOptions);
                return (T?)value;
            }
            finally
            {
                EndMaterializationOperation(operation);
            }
        }

        /// <summary>
        /// Materializes the root into the requested CLR type using one operation-local identity scope, applying configured activators, aliases and root materializers. Developer hooks may run; this is not a concurrent-use operation on the same reader.<br/>
        /// </summary>
        /// <param name="objectType">Exact CLR type whose root materialization or owner registration is requested.<br/></param>
        /// <param name="dzOptions">Optional deserialization policy; see this overload&apos;s remarks for forwarding limitations.<br/></param>
        /// <returns>Materialized root value, possibly null when the source or an activator yields null; conversion and developer-code failures may throw.<br/></returns>
        public object? ToObject(Type objectType, DeserializationOptions? dzOptions = null)
        {
            var key = objectType;
            var fn = _cacheToObject.GetOrAdd(key, static t =>
            {
                // Find the generic version
                var open = typeof(InhetoBinary).Method(nameof(ToObject), new[] { typeof(DeserializationOptions) });
                var m = open.MakeGenericMethod(t);

                // Build: (InhetoBinary self, DeserializationOptions? o) => self.ToObject<T>(o)
                var self = Expression.Parameter(typeof(InhetoBinary), "self");
                var o = Expression.Parameter(typeof(DeserializationOptions), "o");

                var call = Expression.Call(self, m, o);
                var lambda = Expression.Lambda<Func<InhetoBinary, DeserializationOptions?, object?>>(
                    Expression.Convert(call, typeof(object)), self, o);

                return lambda.Compile();
            });

            return fn(this, dzOptions);
        }








