        /// <summary>
        /// Attempts to expose the exact byte payload produced by a registered custom property or custom type serializer without deserializing the value or copying its bytes.<br/>
        /// Missing properties and explicit null markers return <c>false</c>; a present zero-length custom payload returns <c>true</c> with an empty memory slice so callers can preserve null-versus-empty semantics.<br/>
        /// The returned memory is backed by this <see cref="InhetoBinary"/> instance and remains valid only while its underlying payload remains alive.<br/>
        /// </summary>
        /// <param name="propPath">The exact Inheto property path whose custom serialized payload should be inspected.<br/></param>
        /// <param name="payload">Receives a zero-copy read-only slice over the registered serializer's length-prefixed payload.<br/></param>
        /// <returns><c>true</c> when the path contains a custom property or custom type binary payload; otherwise <c>false</c>.<br/></returns>
        /// <exception cref="InvalidDataException">The stored custom value contains malformed or out-of-range length metadata.<br/></exception>
        public bool TryReadCustomBinaryPayload(string propPath, out ReadOnlyMemory<byte> payload)
        {
            ArgumentNullException.ThrowIfNull(propPath);
            var entry = GetNameEntryFromPropPath(propPath);
            if (entry.Kind != InhetoKindMasks.InhetoBaseType ||
                entry.Type.BaseType is InhetoBaseTypes.Unknown or InhetoBaseTypes.Null)
            {
                payload = default;
                return false;
            }

            if (entry.Type.BaseType is InhetoBaseTypes.DuplicateRef or InhetoBaseTypes.DuplicateValue)
                entry = NameHeaderEntry.CreateBorrowed(stream, entry.ValueOffset, entry.Name);

            if (entry.Kind != InhetoKindMasks.InhetoBaseType ||
                entry.Type.BaseType is not (InhetoBaseTypes.CustomProp or InhetoBaseTypes.CustomType))
            {
                payload = default;
                return false;
            }

            stream.Position = entry.ValueOffset;
            if (entry.Type.BaseType == InhetoBaseTypes.CustomType)
            {
                var typeNameLength = stream.Read7BitEncodedInt();
                if (typeNameLength < 0 || stream.Position + typeNameLength > stream.Length)
                    throw new InvalidDataException($"Custom type metadata at '{propPath}' has an invalid type-name length.");

                stream.Position += typeNameLength;
            }

            var payloadLength = stream.Read7BitEncodedInt();
            if (payloadLength < 0 || stream.Position + payloadLength > stream.Length)
                throw new InvalidDataException($"Custom binary payload at '{propPath}' has an invalid byte length.");

            payload = stream.ReadOnlyMemory(checked((int)stream.Position), payloadLength);
            stream.Position += payloadLength;
            return true;
        }

        /// <summary>
        /// Attempts to expose one stored string's natural UTF-8 payload without decoding the string or copying its bytes.<br/>
        /// Missing properties and explicit null markers return <see langword="false"/>; a present empty string returns <see langword="true"/> with an empty memory slice.<br/>
        /// Duplicate-value markers are resolved to their original string entry before the length prefix is inspected.<br/>
        /// The returned memory is backed by this <see cref="InhetoBinary"/> instance and remains valid only while its underlying payload remains alive.<br/>
        /// </summary>
        /// <param name="propPath">The exact Inheto property path whose stored string payload should be borrowed.<br/></param>
        /// <param name="payload">Receives the zero-copy UTF-8 payload without Inheto's length prefix.<br/></param>
        /// <returns><see langword="true"/> for a present string, including an empty string; otherwise <see langword="false"/> for missing or null values.<br/></returns>
        /// <exception cref="InvalidCastException">The path is present but does not contain a string value.<br/></exception>
        /// <exception cref="InvalidDataException">The stored string contains malformed or out-of-range length metadata.<br/></exception>
        public bool TryReadStringUtf8Payload(string propPath, out ReadOnlyMemory<byte> payload)
        {
            ArgumentNullException.ThrowIfNull(propPath);
            bool present = TryReadCompiledStringUtf8Payload(propPath, out payload, out bool handled);
            if (handled)
                return present;
            var entry = GetNameEntryFromPropPath(propPath);
            return TryReadStringUtf8Payload(entry, propPath, out payload);
        }

        /// <summary>
        /// Attempts to expose one logical string property's natural UTF-8 payload while honoring read-time property aliases.<br/>
        /// The exact requested member wins when present; otherwise the registered canonical member and remaining aliases are tried in deterministic order.<br/>
        /// Missing properties and explicit null markers return <see langword="false"/>; a present empty string returns <see langword="true"/> with an empty memory slice.<br/>
        /// The returned memory is backed by this <see cref="InhetoBinary"/> instance and remains valid only while its underlying payload remains alive.<br/>
        /// </summary>
        /// <param name="propPath">Logical property path whose stored string payload should be borrowed.<br/></param>
        /// <param name="dzOptions">Deserialization options containing any property alias groups.<br/></param>
        /// <param name="payload">Receives the zero-copy UTF-8 payload without Inheto's length prefix.<br/></param>
        /// <returns><see langword="true"/> for a present string, including an empty string; otherwise <see langword="false"/> for missing or null values.<br/></returns>
        /// <exception cref="InvalidCastException">The resolved path is present but does not contain a string value.<br/></exception>
        /// <exception cref="InvalidDataException">The stored string contains malformed or out-of-range length metadata.<br/></exception>
        public bool TryReadStringUtf8Payload(
            string propPath,
            DeserializationOptions? dzOptions,
            out ReadOnlyMemory<byte> payload)
        {
            ArgumentNullException.ThrowIfNull(propPath);
            if (dzOptions is null ||
                !dzOptions.Aliases.TryGetGroup(propPath, out _, out _))
            {
                bool present = TryReadCompiledStringUtf8Payload(propPath, out payload, out bool handled);
                if (handled)
                    return present;
            }
            NameHeaderEntry entry = GetNameEntryFromPropPath(propPath, dzOptions, out string resolvedPath);
            return TryReadStringUtf8Payload(entry, resolvedPath, out payload);
        }

        /// <summary>Reads one already-resolved string entry as a borrowed UTF-8 payload.<br/></summary>
        private bool TryReadStringUtf8Payload(
            NameHeaderEntry entry,
            string propPath,
            out ReadOnlyMemory<byte> payload)
        {
            if (entry.Kind != InhetoKindMasks.InhetoBaseType ||
                entry.Type.BaseType is InhetoBaseTypes.Unknown or InhetoBaseTypes.Null)
            {
                payload = default;
                return false;
            }

            if (entry.Type.BaseType is InhetoBaseTypes.DuplicateRef or InhetoBaseTypes.DuplicateValue)
                entry = NameHeaderEntry.CreateBorrowed(stream, entry.ValueOffset, entry.Name);

            if (entry.Kind != InhetoKindMasks.InhetoBaseType ||
                entry.Type.BaseType != InhetoBaseTypes.String)
            {
                throw new InvalidCastException(
                    $"Property path '{propPath}' contains '{entry.Type}' rather than a stored string value.");
            }

            stream.Position = entry.ValueOffset;
            var payloadLength = stream.Read7BitEncodedInt();
            if (payloadLength < 0 || stream.Position + payloadLength > stream.Length)
                throw new InvalidDataException($"String payload at '{propPath}' has an invalid UTF-8 byte length.");

            payload = stream.ReadOnlyMemory(checked((int)stream.Position), payloadLength);
            stream.Position += payloadLength;
            return true;
        }

        internal bool TryReadCustomPropertyPayload(string propPath, out byte[] payload)
        {
            ArgumentNullException.ThrowIfNull(propPath);
            var entry = GetNameEntryFromPropPath(propPath);
            if (entry.Kind != InhetoKindMasks.InhetoBaseType ||
                entry.Type.BaseType is InhetoBaseTypes.Unknown or InhetoBaseTypes.Null)
            {
                payload = default!;
                return false;
            }

            if (entry.Type.BaseType is InhetoBaseTypes.DuplicateRef or InhetoBaseTypes.DuplicateValue)
                entry = NameHeaderEntry.CreateBorrowed(stream, entry.ValueOffset, entry.Name);
            if (entry.Kind != InhetoKindMasks.InhetoBaseType || entry.Type.BaseType != InhetoBaseTypes.CustomProp)
            {
                throw new InvalidOperationException(
                    $"Property path '{propPath}' is stored as '{entry.Type}', so its exact member payload cannot be preserved without invoking a serializer.");
            }

            stream.Position = entry.ValueOffset;
            payload = stream.ReadBytesWithByteLength();
            return true;
        }








    }
}

namespace Inheto
{
    /// <summary>
    /// Provides compact standalone payload codecs for developer-owned binary property handlers.<br/>
    /// These helpers do not create an outer <see cref="InhetoBinary"/> envelope and are suitable for Abraxas property links or ordinary Inheto custom serializers.<br/>
    /// </summary>
    public static class InhetoBinaryCodec
    {
        /// <summary>
        /// Encodes one semantic value as a complete standalone Inheto payload.<br/>
        /// This form is used when a binary consumer needs an ordinary stored property value rather than a custom serializer's already-isolated payload.<br/>
        /// The returned array is caller-owned and includes the Inheto type and shape information needed by <see cref="Decode{TValue}(ReadOnlySpan{byte})"/>.<br/>
        /// </summary>
        /// <typeparam name="TValue">Semantic value type supplied by the caller.<br/></typeparam>
        /// <param name="value">Value to encode, including <see langword="null"/>.<br/></param>
        /// <returns>A newly allocated complete Inheto payload.<br/></returns>
        public static byte[] Encode<TValue>(TValue value)
        {
            if (value is null)
                return new byte[1];
            InhetoBinary encodedBinary = InhetoBinary.FromObject(value);
            ReadOnlySpan<byte> encoded = encodedBinary.RawSpan;
            var payload = new byte[checked(encoded.Length + 1)];
            payload[0] = 1;
            encoded.CopyTo(payload.AsSpan(1));
            return payload;
        }

        /// <summary>
        /// Decodes one complete standalone Inheto payload written by <see cref="Encode{TValue}(TValue)"/>.<br/>
        /// The input span is copied once because the returned object may retain borrowed storage while it is materialized.<br/>
        /// </summary>
        /// <typeparam name="TValue">Semantic value type requested by the caller.<br/></typeparam>
        /// <param name="payload">Complete standalone Inheto payload.<br/></param>
        /// <returns>The decoded value, including <see langword="null"/> when represented by the payload.<br/></returns>
        /// <exception cref="InvalidDataException">Thrown when the payload is empty or malformed.<br/></exception>
        public static TValue? Decode<TValue>(ReadOnlySpan<byte> payload)
        {
            if (payload.IsEmpty)
                throw new InvalidDataException("A standalone Inheto payload requires a null marker.");
            if (payload[0] == 0)
                return default;
            if (payload[0] != 1)
                throw new InvalidDataException($"Unknown standalone Inheto marker '{payload[0]}'.");
            return InhetoBinary.FromStream(new BufferStream(payload[1..].ToArray())).ToObject<TValue>();
        }

        /// <summary>
        /// Encodes one nullable string as a one-byte null marker followed by its UTF-8 content.<br/>
        /// The returned array is the complete custom-property payload and may be stored without another wrapper.<br/>
        /// </summary>
        /// <param name="value">String value to encode, including <see langword="null"/>.<br/></param>
        /// <returns>A newly allocated standalone binary payload.<br/></returns>
        public static byte[] EncodeString(string? value)
        {
            if (value is null)
                return new byte[1];
            int byteCount = Encoding.UTF8.GetByteCount(value);
            var payload = new byte[checked(byteCount + 1)];
            payload[0] = 1;
            Encoding.UTF8.GetBytes(value, payload.AsSpan(1));
            return payload;
        }

        /// <summary>
        /// Decodes one nullable string written by <see cref="EncodeString"/>.<br/>
        /// A zero marker returns <see langword="null"/>; a one marker decodes the remaining bytes as UTF-8.<br/>
        /// </summary>
        /// <param name="payload">Complete standalone binary payload.<br/></param>
        /// <returns>The decoded string or <see langword="null"/>.<br/></returns>
        /// <exception cref="InvalidDataException">Thrown when the payload is empty or carries an unknown marker.<br/></exception>
        public static string? DecodeString(ReadOnlySpan<byte> payload)
        {
            if (payload.IsEmpty)
                throw new InvalidDataException("A nullable string payload requires a null marker.");
            return payload[0] switch
            {
                0 => null,
                1 => Encoding.UTF8.GetString(payload[1..]),
                _ => throw new InvalidDataException($"Unknown nullable string marker '{payload[0]}'.")
            };
        }
    }
}
